import { spawn } from "node:child_process";

const TIMEOUT_MS = 120_000;

export async function generateWithModel(fullModel: string, task: string): Promise<string> {
	const parts = fullModel.split("/");
	if (parts.length < 2) {
		throw new Error(`Invalid model format: ${fullModel}. Expected "provider/model-id"`);
	}
	const provider = parts[0];
	const modelId = parts.slice(1).join("/");

	return new Promise((resolve, reject) => {
		const args = ["--provider", provider, "--model", modelId, "--no-tools", "--no-session", "-p", task];

		const proc = spawn("pi", args, {
			stdio: ["ignore", "pipe", "pipe"],
			env: process.env,
		});

		let stdout = "";
		let stderr = "";

		proc.stdout.on("data", (chunk) => {
			stdout += chunk.toString();
		});
		proc.stderr.on("data", (chunk) => {
			stderr += chunk.toString();
		});

		const timer = setTimeout(() => {
			proc.kill("SIGTERM");
			reject(new Error("Generation timed out after 2 minutes"));
		}, TIMEOUT_MS);

		proc.on("error", (err) => {
			clearTimeout(timer);
			reject(err);
		});

		proc.on("close", (code) => {
			clearTimeout(timer);
			if (code === 0) {
				resolve(stdout.trim());
			} else {
				reject(new Error(`pi exited with code ${code}: ${stderr.slice(0, 500)}`));
			}
		});
	});
}

import http from "node:http";
import { chmodSync, mkdirSync, mkdtempSync, rmSync, statSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import type { DeckConfig } from "./deck-schema.ts";
import type { DeckServerHandle, DeckServerOptions } from "./deck-server.ts";

type RequestResult = {
	status: number;
	headers: http.IncomingHttpHeaders;
	body: string;
};

type StartOverrides = Partial<Omit<DeckServerOptions, "config" | "sessionToken" | "sessionId" | "cwd">> & {
	config?: DeckConfig;
	sessionToken?: string;
	sessionId?: string;
	cwd?: string;
};

let testHome: string;
let handle: DeckServerHandle | null = null;

function makeDeck(title = "Moshi & Deck"): DeckConfig {
	return {
		title,
		slides: [
			{
				id: "choice",
				title: "Pick one",
				options: [{ label: "A", previewHtml: "<div>A</div>" }],
			},
		],
	};
}

async function startServer(overrides: StartOverrides = {}): Promise<DeckServerHandle> {
	const { startDeckServer } = await import("./deck-server.ts");
	const {
		config = makeDeck(),
		sessionToken = "test-token",
		sessionId = "test-session",
		cwd = process.cwd(),
		snapshotDir = join(testHome, "snapshots"),
		...options
	} = overrides;
	return startDeckServer(
		{
			...options,
			config,
			sessionToken,
			sessionId,
			cwd,
			snapshotDir,
		},
		{
			onSubmit: () => {},
			onCancel: () => {},
			onGenerateMore: () => {},
			onRegenerateSlide: () => {},
		}
	);
}

function request(port: number, path = "/", options: { method?: string; headers?: Record<string, string> } = {}): Promise<RequestResult> {
	return new Promise((resolve, reject) => {
		const req = http.request(
			{
				hostname: "127.0.0.1",
				port,
				path,
				method: options.method ?? "GET",
				agent: false,
				headers: { Connection: "close", ...options.headers },
			},
			(res) => {
				const chunks: Buffer[] = [];
				res.on("data", (chunk: Buffer) => chunks.push(chunk));
				res.on("end", () => {
					resolve({
						status: res.statusCode ?? 0,
						headers: res.headers,
						body: Buffer.concat(chunks).toString("utf8"),
					});
				});
			}
		);
		req.on("error", reject);
		req.end();
	});
}

beforeEach(() => {
	testHome = mkdtempSync(join(tmpdir(), "deck-server-test-"));
	vi.resetModules();
	vi.stubEnv("HOME", testHome);
});

afterEach(() => {
	if (handle) {
		handle.close("test-cleanup");
		handle = null;
	}
	vi.unstubAllEnvs();
	rmSync(testHome, { recursive: true, force: true });
});

describe("startDeckServer Moshi discovery", () => {
	it("starts on a Moshi-discoverable low port by default", async () => {
		handle = await startServer();

		expect(handle.port).toBeGreaterThanOrEqual(8377);
		expect(handle.port).toBeLessThanOrEqual(8396);
		expect(handle.url).toContain(`http://localhost:${handle.port}`);
		expect(handle.url).toContain("session=test-token");
	});

	it("scans forward when the first low port is already in use", async () => {
		const first = await startServer({ sessionToken: "first-token", sessionId: "first-session" });
		try {
			handle = await startServer({ sessionToken: "[REDACTED]", sessionId: "second-session" });

			expect(handle.port).not.toBe(first.port);
			expect(handle.port).toBeGreaterThanOrEqual(8377);
			expect(handle.port).toBeLessThanOrEqual(8396);
		} finally {
			first.close("test-cleanup");
		}
	});

	it("serves a stateless tokenless landing shell without the Sec-Fetch-Mode gate", async () => {
		handle = await startServer();

		const res = await request(handle.port, "/", { headers: { "Sec-Fetch-Mode": "cors" } });

		expect(res.status).toBe(200);
		expect(res.headers["content-type"]).toContain("text/html");
		expect(res.body).toContain("<title>Moshi &amp; Deck</title>");
		expect(res.body).toContain('location.replace("/?session=test-token")');
	});

	it("answers HEAD discovery probes without a session token", async () => {
		handle = await startServer();

		const res = await request(handle.port, "/", { method: "HEAD" });

		expect(res.status).toBe(200);
		expect(res.headers["content-type"]).toContain("text/html");
		expect(res.body).toBe("");
	});

	it("rejects non-loopback Host headers before serving the tokenless shell", async () => {
		handle = await startServer();

		const res = await request(handle.port, "/", { headers: { Host: "attacker.example" } });

		expect(res.status).toBe(403);
		expect(res.body).toBe("Invalid host");
	});

	it("accepts bracketed IPv6 loopback Host headers", async () => {
		handle = await startServer();

		const res = await request(handle.port, "/", { headers: { Host: `[::1]:${handle.port}` } });

		expect(res.status).toBe(200);
		expect(res.body).toContain('location.replace("/?session=test-token")');
	});

	it("keeps the sessions file owner-only when replacing a stale tmp file", async () => {
		const piDir = join(testHome, ".pi");
		mkdirSync(piDir, { recursive: true });
		const tmpSessionsFile = join(piDir, "deck-sessions.json.tmp");
		writeFileSync(tmpSessionsFile, "{}", { mode: 0o644 });
		chmodSync(tmpSessionsFile, 0o644);

		handle = await startServer();

		const mode = statSync(join(piDir, "deck-sessions.json")).mode & 0o777;
		expect(mode).toBe(0o600);
	});
});

import { describe, it, expect } from "vitest";
import { validateDeckConfig, isDeckOption, validateSavedDeck, deriveDeckStatusFromFolderName } from "./deck-schema.ts";

function validDeck(slideOverrides: Record<string, unknown> = {}, optionOverrides: Record<string, unknown> = {}) {
	return {
		slides: [{
			id: "s1",
			title: "Pick one",
			...slideOverrides,
			options: [
				{ label: "A", previewHtml: "<div>A</div>", ...optionOverrides },
				{ label: "B", previewHtml: "<div>B</div>" },
			],
		}],
	};
}

describe("validateDeckConfig", () => {
	describe("previewHtml (existing behavior)", () => {
		it("accepts valid deck with previewHtml", () => {
			const config = validateDeckConfig(validDeck());
			expect(config.slides).toHaveLength(1);
			expect(config.slides[0].options).toHaveLength(2);
		});

		it("rejects option with empty previewHtml and no previewBlocks", () => {
			expect(() => validateDeckConfig(validDeck({}, { previewHtml: "" }))).toThrow(
				"must have non-empty previewHtml or previewBlocks"
			);
		});

		it("rejects option with no preview at all", () => {
			expect(() => validateDeckConfig({
				slides: [{ id: "s1", title: "T", options: [{ label: "A" }] }],
			})).toThrow("must have non-empty previewHtml or previewBlocks");
		});

		it("rejects non-string previewHtml with type error, not missing-preview error", () => {
			expect(() => validateDeckConfig({
				slides: [{ id: "s1", title: "T", options: [{ label: "A", previewHtml: 42 }] }],
			})).toThrow("previewHtml must be a string");
		});
	});

	describe("previewBlocks", () => {
		it("accepts option with previewBlocks html block", () => {
			const config = validateDeckConfig({
				slides: [{
					id: "s1", title: "T",
					options: [
						{ label: "A", previewBlocks: [{ type: "html", content: "<p>Hello</p>" }] },
					],
				}],
			});
			expect(config.slides[0].options[0].previewBlocks).toHaveLength(1);
		});

		it("accepts mermaid block", () => {
			const config = validateDeckConfig({
				slides: [{
					id: "s1", title: "T",
					options: [
						{ label: "A", previewBlocks: [{ type: "mermaid", content: "graph LR\n  A-->B" }] },
					],
				}],
			});
			expect(config.slides[0].options[0].previewBlocks![0].type).toBe("mermaid");
		});

		it("accepts mermaid block with theme overrides", () => {
			const config = validateDeckConfig({
				slides: [{
					id: "s1", title: "T",
					options: [
						{ label: "A", previewBlocks: [{ type: "mermaid", content: "graph LR\n  A-->B", theme: { primaryColor: "#ff0000" } }] },
					],
				}],
			});
			const block = config.slides[0].options[0].previewBlocks![0];
			expect(block.type).toBe("mermaid");
		});

		it("accepts code block", () => {
			const config = validateDeckConfig({
				slides: [{
					id: "s1", title: "T",
					options: [
						{ label: "A", previewBlocks: [{ type: "code", code: "const x = 1;", lang: "ts" }] },
					],
				}],
			});
			const block = config.slides[0].options[0].previewBlocks![0];
			expect(block.type).toBe("code");
		});

		it("accepts image block with src, alt, and caption", () => {
			const config = validateDeckConfig({
				slides: [{
					id: "s1", title: "T",
					options: [
						{ label: "A", previewBlocks: [{ type: "image", src: "/tmp/img.png", alt: "test image", caption: "Figure 1" }] },
					],
				}],
			});
			const block = config.slides[0].options[0].previewBlocks![0];
			expect(block.type).toBe("image");
		});

		it("accepts multiple blocks in one option", () => {
			const config = validateDeckConfig({
				slides: [{
					id: "s1", title: "T",
					options: [{
						label: "A",
						previewBlocks: [
							{ type: "mermaid", content: "graph TD\n  A-->B" },
							{ type: "code", code: "app.listen(3000)", lang: "ts" },
							{ type: "html", content: "<p>Notes</p>" },
						],
					}],
				}],
			});
			expect(config.slides[0].options[0].previewBlocks).toHaveLength(3);
		});

		it("rejects both previewHtml and previewBlocks", () => {
			expect(() => validateDeckConfig({
				slides: [{
					id: "s1", title: "T",
					options: [{ label: "A", previewHtml: "<div>A</div>", previewBlocks: [{ type: "html", content: "<p>B</p>" }] }],
				}],
			})).toThrow("not both");
		});

		it("rejects empty previewBlocks array", () => {
			expect(() => validateDeckConfig({
				slides: [{
					id: "s1", title: "T",
					options: [{ label: "A", previewBlocks: [] }],
				}],
			})).toThrow("must have non-empty previewHtml or previewBlocks");
		});

		it("rejects code block with empty code", () => {
			expect(() => validateDeckConfig({
				slides: [{
					id: "s1", title: "T",
					options: [{ label: "A", previewBlocks: [{ type: "code", code: "", lang: "ts" }] }],
				}],
			})).toThrow("non-empty code");
		});

		it("rejects code block with empty lang", () => {
			expect(() => validateDeckConfig({
				slides: [{
					id: "s1", title: "T",
					options: [{ label: "A", previewBlocks: [{ type: "code", code: "x", lang: "" }] }],
				}],
			})).toThrow("non-empty lang");
		});

		it("rejects mermaid block with empty content", () => {
			expect(() => validateDeckConfig({
				slides: [{
					id: "s1", title: "T",
					options: [{ label: "A", previewBlocks: [{ type: "mermaid", content: "" }] }],
				}],
			})).toThrow("non-empty content");
		});

		it("rejects image block without alt", () => {
			expect(() => validateDeckConfig({
				slides: [{
					id: "s1", title: "T",
					options: [{ label: "A", previewBlocks: [{ type: "image", src: "/tmp/x.png", alt: "" }] }],
				}],
			})).toThrow("non-empty alt");
		});

		it("rejects image block without src", () => {
			expect(() => validateDeckConfig({
				slides: [{
					id: "s1", title: "T",
					options: [{ label: "A", previewBlocks: [{ type: "image", src: "", alt: "test" }] }],
				}],
			})).toThrow("non-empty src");
		});

		it("rejects invalid block type", () => {
			expect(() => validateDeckConfig({
				slides: [{
					id: "s1", title: "T",
					options: [{ label: "A", previewBlocks: [{ type: "video", src: "/tmp/x.mp4" }] }],
				}],
			})).toThrow("type must be one of");
		});

		it("rejects mermaid theme with non-string values", () => {
			expect(() => validateDeckConfig({
				slides: [{
					id: "s1", title: "T",
					options: [{ label: "A", previewBlocks: [{ type: "mermaid", content: "graph LR\n A-->B", theme: { primaryColor: 123 } }] }],
				}],
			})).toThrow("must be a string");
		});
	});

	describe("aside", () => {
		it("accepts option with aside string", () => {
			const config = validateDeckConfig({
				slides: [{
					id: "s1", title: "T",
					options: [{ label: "A", previewHtml: "<div>A</div>", aside: "Pros: fast\nCons: complex" }],
				}],
			});
			expect(config.slides[0].options[0].aside).toBe("Pros: fast\nCons: complex");
		});

		it("accepts option without aside", () => {
			const config = validateDeckConfig({
				slides: [{
					id: "s1", title: "T",
					options: [{ label: "A", previewHtml: "<div>A</div>" }],
				}],
			});
			expect(config.slides[0].options[0].aside).toBeUndefined();
		});

		it("rejects non-string aside", () => {
			expect(() => validateDeckConfig({
				slides: [{
					id: "s1", title: "T",
					options: [{ label: "A", previewHtml: "<div>A</div>", aside: 42 }],
				}],
			})).toThrow("aside must be a string");
		});
	});

	describe("columns", () => {
		it("accepts columns: 1", () => {
			const config = validateDeckConfig({
				slides: [{
					id: "s1", title: "T", columns: 1,
					options: [{ label: "A", previewHtml: "<div>A</div>" }],
				}],
			});
			expect(config.slides[0].columns).toBe(1);
		});

		it("accepts columns: 2", () => {
			const config = validateDeckConfig({
				slides: [{
					id: "s1", title: "T", columns: 2,
					options: [{ label: "A", previewHtml: "<div>A</div>" }],
				}],
			});
			expect(config.slides[0].columns).toBe(2);
		});

		it("accepts columns: 3", () => {
			const config = validateDeckConfig({
				slides: [{
					id: "s1", title: "T", columns: 3,
					options: [{ label: "A", previewHtml: "<div>A</div>" }],
				}],
			});
			expect(config.slides[0].columns).toBe(3);
		});

		it("accepts columns: 4", () => {
			const config = validateDeckConfig({
				slides: [{
					id: "s1", title: "T", columns: 4,
					options: [{ label: "A", previewHtml: "<div>A</div>" }],
				}],
			});
			expect(config.slides[0].columns).toBe(4);
		});

		it("rejects columns: 0", () => {
			expect(() => validateDeckConfig({
				slides: [{
					id: "s1", title: "T", columns: 0,
					options: [{ label: "A", previewHtml: "<div>A</div>" }],
				}],
			})).toThrow("columns must be 1, 2, 3, or 4");
		});

		it("accepts omitted columns (auto-detect)", () => {
			const config = validateDeckConfig(validDeck());
			expect(config.slides[0].columns).toBeUndefined();
		});
	});

	describe("reserved ids", () => {
		it('rejects slide id "summary"', () => {
			expect(() => validateDeckConfig({
				slides: [{
					id: "summary", title: "T",
					options: [{ label: "A", previewHtml: "<div>A</div>" }],
				}],
			})).toThrow('"summary" is reserved');
		});
	});
});

describe("isDeckOption with blocks", () => {
	it("accepts option with previewHtml", () => {
		expect(isDeckOption({ label: "A", previewHtml: "<div>A</div>" })).toBe(true);
	});

	it("accepts option with previewBlocks", () => {
		expect(isDeckOption({
			label: "A",
			previewBlocks: [{ type: "html", content: "<p>B</p>" }],
		})).toBe(true);
	});

	it("rejects option with both", () => {
		expect(isDeckOption({
			label: "A",
			previewHtml: "<div>A</div>",
			previewBlocks: [{ type: "html", content: "<p>B</p>" }],
		})).toBe(false);
	});

	it("rejects option with neither", () => {
		expect(isDeckOption({ label: "A" })).toBe(false);
	});

	it("rejects empty previewBlocks array", () => {
		expect(isDeckOption({ label: "A", previewBlocks: [] })).toBe(false);
	});

	it("rejects empty label", () => {
		expect(isDeckOption({ label: "", previewHtml: "<div>A</div>" })).toBe(false);
	});

	it("accepts option with aside", () => {
		expect(isDeckOption({ label: "A", previewHtml: "<div>A</div>", aside: "some notes" })).toBe(true);
	});

	it("rejects non-string aside", () => {
		expect(isDeckOption({ label: "A", previewHtml: "<div>A</div>", aside: 123 })).toBe(false);
	});

	it("rejects non-string previewHtml even with valid previewBlocks", () => {
		expect(isDeckOption({
			label: "A",
			previewHtml: 42,
			previewBlocks: [{ type: "code", code: "const x = 1;", lang: "ts" }],
		})).toBe(false);
	});

	it("rejects previewBlocks with invalid block structure", () => {
		expect(isDeckOption({
			label: "A",
			previewBlocks: [{ type: "code" }],
		})).toBe(false);
	});

	it("rejects previewBlocks with unknown block type", () => {
		expect(isDeckOption({
			label: "A",
			previewBlocks: [{ type: "video", src: "/tmp/x.mp4" }],
		})).toBe(false);
	});

	it("accepts previewBlocks with valid block structure", () => {
		expect(isDeckOption({
			label: "A",
			previewBlocks: [{ type: "code", code: "const x = 1;", lang: "ts" }],
		})).toBe(true);
	});
});

describe("validateSavedDeck", () => {
	const minConfig = {
		slides: [{ id: "s1", title: "Slide 1", options: [{ label: "A", previewHtml: "<div>A</div>" }] }],
	};

	it("validates a minimal saved deck", () => {
		const result = validateSavedDeck({ config: minConfig, selections: { s1: "A" }, savedAt: "2026-01-01" });
		expect(result.config.slides).toHaveLength(1);
		expect(result.selections).toEqual({ s1: "A" });
		expect(result.savedAt).toBe("2026-01-01");
	});

	it("handles missing selections gracefully", () => {
		const result = validateSavedDeck({ config: minConfig });
		expect(result.selections).toEqual({});
	});

	it("filters non-string selection values", () => {
		const result = validateSavedDeck({ config: minConfig, selections: { s1: "A", s2: 42 } });
		expect(result.selections).toEqual({ s1: "A" });
	});

	it("provides default savedAt when missing", () => {
		const result = validateSavedDeck({ config: minConfig });
		expect(result.savedAt).toBeTruthy();
	});

	it("preserves savedFrom metadata", () => {
		const from = { cwd: "/projects/app", branch: "main", sessionId: "abc" };
		const result = validateSavedDeck({ config: minConfig, savedFrom: from });
		expect(result.savedFrom).toEqual(from);
	});

	it("rejects non-object input", () => {
		expect(() => validateSavedDeck("string")).toThrow("must be an object");
		expect(() => validateSavedDeck(null)).toThrow("must be an object");
		expect(() => validateSavedDeck([])).toThrow("must be an object");
	});

	it("rejects invalid config", () => {
		expect(() => validateSavedDeck({ config: "bad" })).toThrow();
		expect(() => validateSavedDeck({ config: { slides: [] } })).toThrow("non-empty array");
	});
});

describe("deriveDeckStatusFromFolderName", () => {
	it("returns 'submitted' for folders ending with -submitted", () => {
		expect(deriveDeckStatusFromFolderName("tabs-myapp-main-2026-03-01-103045-submitted")).toBe("submitted");
	});

	it("returns 'cancelled' for folders ending with -cancelled", () => {
		expect(deriveDeckStatusFromFolderName("tabs-myapp-main-2026-03-01-103045-cancelled")).toBe("cancelled");
	});

	it("returns 'in-progress' for folders without status suffix", () => {
		expect(deriveDeckStatusFromFolderName("tabs-myapp-main-2026-03-01-103045")).toBe("in-progress");
	});

	it("returns 'in-progress' for random folder names", () => {
		expect(deriveDeckStatusFromFolderName("my-deck")).toBe("in-progress");
	});
});

import { readFileSync, writeFileSync, renameSync } from "node:fs";
import { join } from "node:path";
import { homedir } from "node:os";

const SETTINGS_PATH = join(homedir(), ".pi", "agent", "settings.json");

export interface DeckThemeSettings {
	mode?: "auto" | "light" | "dark";
	toggleHotkey?: string;
}

export interface DesignDeckSettings {
	port?: number;
	browser?: string;
	theme?: DeckThemeSettings;
	snapshotDir?: string;
	autoSaveOnSubmit?: boolean;
	generateModel?: string;
}

export function loadSettings(): DesignDeckSettings {
	try {
		const data = JSON.parse(readFileSync(SETTINGS_PATH, "utf-8")) as Record<string, unknown>;
		const designDeck = data.designDeck;
		if (designDeck && typeof designDeck === "object" && !Array.isArray(designDeck)) {
			return designDeck as DesignDeckSettings;
		}

		const interview = data.interview;
		if (interview && typeof interview === "object" && !Array.isArray(interview)) {
			const oldModel = (interview as Record<string, unknown>).deckGenerateModel;
			if (typeof oldModel === "string" && oldModel.trim() !== "") {
				const nextDesignDeck: Record<string, unknown> = { generateModel: oldModel };
				data.designDeck = nextDesignDeck;
				delete (interview as Record<string, unknown>).deckGenerateModel;
				const tempFile = SETTINGS_PATH + ".tmp";
				writeFileSync(tempFile, JSON.stringify(data, null, 2) + "\n");
				renameSync(tempFile, SETTINGS_PATH);
				return nextDesignDeck as DesignDeckSettings;
			}
		}
		return {};
	} catch {
		return {};
	}
}

export function saveGenerateModel(model: string | null): void {
	let data: Record<string, unknown> = {};
	try {
		data = JSON.parse(readFileSync(SETTINGS_PATH, "utf-8"));
	} catch {}
	if (!data.designDeck || typeof data.designDeck !== "object" || Array.isArray(data.designDeck)) {
		data.designDeck = {};
	}
	const designDeck = data.designDeck as Record<string, unknown>;
	if (model) {
		designDeck.generateModel = model;
	} else {
		delete designDeck.generateModel;
	}
	const tempFile = SETTINGS_PATH + ".tmp";
	writeFileSync(tempFile, JSON.stringify(data, null, 2) + "\n");
	renameSync(tempFile, SETTINGS_PATH);
}

export type PreviewBlock =
	| { type: "html"; content: string }
	| { type: "mermaid"; content: string; theme?: Record<string, string> }
	| { type: "code"; code: string; lang: string }
	| { type: "image"; src: string; alt: string; caption?: string };

export interface DeckOption {
	label: string;
	description?: string;
	aside?: string;
	previewHtml?: string;
	previewBlocks?: PreviewBlock[];
	recommended?: boolean;
}

export interface DeckSlide {
	id: string;
	title: string;
	context?: string;
	columns?: 1 | 2 | 3 | 4;
	options: DeckOption[];
}

export interface DeckConfig {
	title?: string;
	slides: DeckSlide[];
}

function validatePreviewBlock(block: unknown, slideId: string, label: string, index: number): PreviewBlock {
	if (!block || typeof block !== "object") {
		throw new Error(`Slide "${slideId}": option "${label}" previewBlocks[${index}] must be an object`);
	}

	const b = block as Record<string, unknown>;
	const validTypes = ["html", "mermaid", "code", "image"];

	if (typeof b.type !== "string" || !validTypes.includes(b.type)) {
		throw new Error(`Slide "${slideId}": option "${label}" previewBlocks[${index}] type must be one of: ${validTypes.join(", ")}`);
	}

	if (b.type === "html") {
		if (typeof b.content !== "string" || b.content.trim() === "") {
			throw new Error(`Slide "${slideId}": option "${label}" html block must have non-empty content`);
		}
	} else if (b.type === "mermaid") {
		if (typeof b.content !== "string" || b.content.trim() === "") {
			throw new Error(`Slide "${slideId}": option "${label}" mermaid block must have non-empty content`);
		}
		if (b.theme !== undefined) {
			if (!b.theme || typeof b.theme !== "object" || Array.isArray(b.theme)) {
				throw new Error(`Slide "${slideId}": option "${label}" mermaid block theme must be an object of string values`);
			}
			for (const [key, val] of Object.entries(b.theme as Record<string, unknown>)) {
				if (typeof val !== "string") {
					throw new Error(`Slide "${slideId}": option "${label}" mermaid block theme.${key} must be a string`);
				}
			}
		}
	} else if (b.type === "code") {
		if (typeof b.code !== "string" || b.code.trim() === "") {
			throw new Error(`Slide "${slideId}": option "${label}" code block must have non-empty code`);
		}
		if (typeof b.lang !== "string" || b.lang.trim() === "") {
			throw new Error(`Slide "${slideId}": option "${label}" code block must have non-empty lang`);
		}
	} else if (b.type === "image") {
		if (typeof b.src !== "string" || b.src.trim() === "") {
			throw new Error(`Slide "${slideId}": option "${label}" image block must have non-empty src`);
		}
		if (typeof b.alt !== "string" || b.alt.trim() === "") {
			throw new Error(`Slide "${slideId}": option "${label}" image block must have non-empty alt`);
		}
		if (b.caption !== undefined && typeof b.caption !== "string") {
			throw new Error(`Slide "${slideId}": option "${label}" image block caption must be a string`);
		}
	}

	return b as unknown as PreviewBlock;
}

function validateDeckOption(option: unknown, slideId: string, index: number): DeckOption {
	if (!option || typeof option !== "object") {
		throw new Error(`Slide "${slideId}": option at index ${index} must be an object`);
	}

	const obj = option as Record<string, unknown>;

	if (typeof obj.label !== "string" || obj.label.trim() === "") {
		throw new Error(`Slide "${slideId}": option at index ${index} must have a non-empty label`);
	}

	if (obj.previewHtml !== undefined && typeof obj.previewHtml !== "string") {
		throw new Error(
			`Slide "${slideId}": option "${obj.label}" previewHtml must be a string`
		);
	}

	const hasHtml = typeof obj.previewHtml === "string" && obj.previewHtml.trim() !== "";
	const hasBlocks = Array.isArray(obj.previewBlocks) && obj.previewBlocks.length > 0;

	if (hasHtml && hasBlocks) {
		throw new Error(
			`Slide "${slideId}": option "${obj.label}" must have either previewHtml or previewBlocks, not both`
		);
	}

	if (!hasHtml && !hasBlocks) {
		throw new Error(
			`Slide "${slideId}": option "${obj.label}" must have non-empty previewHtml or previewBlocks`
		);
	}

	if (hasBlocks) {
		for (let i = 0; i < (obj.previewBlocks as unknown[]).length; i++) {
			validatePreviewBlock((obj.previewBlocks as unknown[])[i], slideId, obj.label as string, i);
		}
	}

	if (obj.description !== undefined && typeof obj.description !== "string") {
		throw new Error(`Slide "${slideId}": option "${obj.label}" description must be a string`);
	}

	if (obj.aside !== undefined && typeof obj.aside !== "string") {
		throw new Error(`Slide "${slideId}": option "${obj.label}" aside must be a string`);
	}

	if (obj.recommended !== undefined && typeof obj.recommended !== "boolean") {
		throw new Error(`Slide "${slideId}": option "${obj.label}" recommended must be boolean`);
	}

	return obj as unknown as DeckOption;
}

function validateDeckSlide(slide: unknown, index: number): DeckSlide {
	if (!slide || typeof slide !== "object") {
		throw new Error(`Slide at index ${index} must be an object`);
	}

	const obj = slide as Record<string, unknown>;

	if (typeof obj.id !== "string" || obj.id.trim() === "") {
		throw new Error(`Slide at index ${index} must have a non-empty id`);
	}

	if (obj.id === "summary") {
		throw new Error(`Slide at index ${index}: id "summary" is reserved`);
	}

	if (typeof obj.title !== "string" || obj.title.trim() === "") {
		throw new Error(`Slide "${obj.id}": title must be a non-empty string`);
	}

	if (obj.context !== undefined && typeof obj.context !== "string") {
		throw new Error(`Slide "${obj.id}": context must be a string`);
	}

	if (obj.columns !== undefined) {
		if (obj.columns !== 1 && obj.columns !== 2 && obj.columns !== 3 && obj.columns !== 4) {
			throw new Error(`Slide "${obj.id}": columns must be 1, 2, 3, or 4`);
		}
	}

	if (!Array.isArray(obj.options) || obj.options.length === 0) {
		throw new Error(`Slide "${obj.id}": options must be a non-empty array`);
	}

	obj.options.forEach((option, optionIndex) => {
		validateDeckOption(option, obj.id as string, optionIndex);
	});

	return obj as unknown as DeckSlide;
}

export function isDeckOption(value: unknown): value is DeckOption {
	if (!value || typeof value !== "object") return false;
	const obj = value as Record<string, unknown>;
	if (typeof obj.label !== "string" || obj.label.trim() === "") return false;
	if (obj.previewHtml !== undefined && typeof obj.previewHtml !== "string") return false;

	const hasHtml = typeof obj.previewHtml === "string" && obj.previewHtml.trim() !== "";
	const hasBlocks = Array.isArray(obj.previewBlocks) && obj.previewBlocks.length > 0;
	if (!hasHtml && !hasBlocks) return false;
	if (hasHtml && hasBlocks) return false;

	if (hasBlocks) {
		try {
			for (let i = 0; i < (obj.previewBlocks as unknown[]).length; i++) {
				validatePreviewBlock((obj.previewBlocks as unknown[])[i], "check", obj.label as string, i);
			}
		} catch {
			return false;
		}
	}

	if (obj.description !== undefined && typeof obj.description !== "string") return false;
	if (obj.aside !== undefined && typeof obj.aside !== "string") return false;
	if (obj.recommended !== undefined && typeof obj.recommended !== "boolean") return false;
	return true;
}

export function validateDeckConfig(data: unknown): DeckConfig {
	if (!data || typeof data !== "object" || Array.isArray(data)) {
		throw new Error("Deck config must be an object");
	}

	const obj = data as Record<string, unknown>;

	if (obj.title !== undefined && typeof obj.title !== "string") {
		throw new Error("Deck config title must be a string");
	}

	if (!Array.isArray(obj.slides) || obj.slides.length === 0) {
		throw new Error("Deck config slides must be a non-empty array");
	}

	const ids = new Set<string>();
	obj.slides.forEach((slide, index) => {
		const validated = validateDeckSlide(slide, index);
		if (ids.has(validated.id)) {
			throw new Error(`Duplicate slide id: "${validated.id}"`);
		}
		ids.add(validated.id);
	});

	return obj as unknown as DeckConfig;
}

export interface SavedDeckData {
	config: DeckConfig;
	selections: Record<string, string>;
	savedAt: string;
	id?: string;
	status?: "submitted" | "in-progress" | "cancelled";
	modifiedAt?: string;
	notes?: Record<string, string>;
	finalNotes?: string;
	savedFrom?: {
		cwd: string;
		branch: string | null;
		sessionId: string;
	};
}

export type SavedDeckStatus = NonNullable<SavedDeckData["status"]>;

export function deriveDeckStatusFromFolderName(folderName: string): SavedDeckStatus {
	if (folderName.endsWith("-submitted")) return "submitted";
	if (folderName.endsWith("-cancelled")) return "cancelled";
	return "in-progress";
}

export function validateSavedDeck(data: unknown): SavedDeckData {
	if (!data || typeof data !== "object" || Array.isArray(data)) {
		throw new Error("Invalid saved deck: must be an object");
	}

	const obj = data as Record<string, unknown>;
	const config = validateDeckConfig(obj.config);

	const selections: Record<string, string> = {};
	if (obj.selections && typeof obj.selections === "object" && !Array.isArray(obj.selections)) {
		for (const [key, val] of Object.entries(obj.selections as Record<string, unknown>)) {
			if (typeof val === "string") selections[key] = val;
		}
	}

	const notes: Record<string, string> = {};
	if (obj.notes && typeof obj.notes === "object" && !Array.isArray(obj.notes)) {
		for (const [key, val] of Object.entries(obj.notes as Record<string, unknown>)) {
			if (typeof val === "string") notes[key] = val;
		}
	}

	const status =
		obj.status === "submitted" || obj.status === "in-progress" || obj.status === "cancelled"
			? obj.status
			: undefined;

	return {
		config,
		selections,
		savedAt: typeof obj.savedAt === "string" ? obj.savedAt : new Date().toISOString(),
		...(typeof obj.id === "string" && obj.id.trim() !== "" ? { id: obj.id } : {}),
		...(status !== undefined ? { status } : {}),
		...(typeof obj.modifiedAt === "string" ? { modifiedAt: obj.modifiedAt } : {}),
		...(Object.keys(notes).length > 0 ? { notes } : {}),
		...(typeof obj.finalNotes === "string" ? { finalNotes: obj.finalNotes } : {}),
		...(obj.savedFrom && typeof obj.savedFrom === "object"
			? { savedFrom: obj.savedFrom as NonNullable<SavedDeckData["savedFrom"]> }
			: {}),
	};
}

import { execSync } from "node:child_process";
import { readFileSync, existsSync, renameSync, writeFileSync, mkdirSync, chmodSync } from "node:fs";
import type { IncomingMessage, ServerResponse } from "node:http";
import { homedir } from "node:os";
import { join } from "node:path";

export function getGitBranch(cwd: string): string | null {
	try {
		const branch = execSync("git rev-parse --abbrev-ref HEAD", {
			cwd,
			encoding: "utf8",
			timeout: 2000,
			stdio: ["pipe", "pipe", "pipe"],
		}).trim();
		return branch || null;
	} catch {
		return null;
	}
}

export function normalizePath(path: string): string {
	const home = homedir();
	if (path.startsWith(home)) {
		return "~" + path.slice(home.length);
	}
	return path;
}

export interface SessionEntry {
	id: string;
	url: string;
	cwd: string;
	gitBranch: string | null;
	title: string;
	startedAt: number;
	lastSeen: number;
}

interface SessionsData {
	sessions: SessionEntry[];
}

const SESSIONS_FILE = join(homedir(), ".pi", "deck-sessions.json");
const STALE_PRUNE_MS = 60000;

function ensurePiDir(): void {
	const piDir = join(homedir(), ".pi");
	if (!existsSync(piDir)) {
		mkdirSync(piDir, { recursive: true });
	}
}

function readSessions(): SessionsData {
	try {
		if (!existsSync(SESSIONS_FILE)) {
			return { sessions: [] };
		}
		const data = readFileSync(SESSIONS_FILE, "utf8");
		const parsed = JSON.parse(data);
		if (!parsed.sessions || !Array.isArray(parsed.sessions)) {
			return { sessions: [] };
		}
		return parsed as SessionsData;
	} catch {
		return { sessions: [] };
	}
}

function writeSessions(data: SessionsData): void {
	ensurePiDir();
	const tempFile = SESSIONS_FILE + ".tmp";
	writeFileSync(tempFile, JSON.stringify(data, null, 2), { mode: 0o600 });
	// writeFileSync's mode only applies on creation; a pre-existing .tmp keeps its old mode.
	chmodSync(tempFile, 0o600);
	renameSync(tempFile, SESSIONS_FILE);
}

function pruneStale(sessions: SessionEntry[]): SessionEntry[] {
	const now = Date.now();
	return sessions.filter((s) => now - s.lastSeen < STALE_PRUNE_MS);
}

export function touchSession(entry: SessionEntry): void {
	const data = readSessions();
	data.sessions = pruneStale(data.sessions);
	const existing = data.sessions.find((s) => s.id === entry.id);
	if (existing) {
		existing.lastSeen = Date.now();
		existing.url = entry.url;
		existing.cwd = entry.cwd;
		existing.gitBranch = entry.gitBranch;
		existing.title = entry.title;
		existing.startedAt = entry.startedAt;
	} else {
		data.sessions.push({ ...entry, lastSeen: Date.now() });
	}
	writeSessions(data);
}

export function registerSession(entry: SessionEntry): void {
	touchSession(entry);
}

export function unregisterSession(sessionId: string): void {
	const data = readSessions();
	data.sessions = data.sessions.filter((s) => s.id !== sessionId);
	writeSessions(data);
}

export const MAX_BODY_SIZE = 15 * 1024 * 1024;

class BodyTooLargeError extends Error {
	statusCode = 413;
}

const INLINE_JSON_ESCAPES: Record<string, string> = {
	"<": "\\u003c",
	">": "\\u003e",
	"&": "\\u0026",
};

export function safeInlineJSON(data: unknown): string {
	return JSON.stringify(data).replace(/[<>&]/g, (char) => INLINE_JSON_ESCAPES[char]);
}

export function sendText(res: ServerResponse, status: number, text: string) {
	res.writeHead(status, {
		"Content-Type": "text/plain; charset=utf-8",
		"Cache-Control": "no-store",
	});
	res.end(text);
}

export function sendJson(res: ServerResponse, status: number, payload: unknown) {
	res.writeHead(status, {
		"Content-Type": "application/json",
		"Cache-Control": "no-store",
	});
	res.end(JSON.stringify(payload));
}

async function parseJSONBody(req: IncomingMessage): Promise<unknown> {
	return new Promise((resolve, reject) => {
		let body = "";
		let size = 0;

		req.on("data", (chunk: Buffer) => {
			size += chunk.length;
			if (size > MAX_BODY_SIZE) {
				req.destroy();
				reject(new BodyTooLargeError("Request body too large"));
				return;
			}
			body += chunk.toString();
		});

		req.on("end", () => {
			try {
				resolve(JSON.parse(body));
			} catch {
				reject(new Error("Invalid JSON"));
			}
		});

		req.on("error", reject);
	});
}

export async function safeParseBody(req: IncomingMessage, res: ServerResponse): Promise<unknown | null> {
	try {
		return await parseJSONBody(req);
	} catch (err) {
		if (err instanceof BodyTooLargeError) {
			sendJson(res, err.statusCode, { ok: false, error: err.message });
		} else {
			sendJson(res, 400, { ok: false, error: err instanceof Error ? err.message : "Invalid body" });
		}
		return null;
	}
}

export function validateTokenQuery(url: URL, expectedToken: string, res: ServerResponse): boolean {
	const token = [REDACTED]"session");
	if (token !== expectedToken) {
		sendText(res, 403, "Invalid session");
		return false;
	}
	return true;
}

export function validateTokenBody(body: unknown, expectedToken: string, res: ServerResponse): boolean {
	if (!body || typeof body !== "object") {
		sendJson(res, 400, { ok: false, error: "Invalid request body" });
		return false;
	}
	const token = (body as { token?: string }).token;
	if (token !== expectedToken) {
		sendJson(res, 403, { ok: false, error: "Invalid session" });
		return false;
	}
	return true;
}

import type { DeckSlide } from "./deck-schema.ts";

function formatHintForSlide(slide: DeckSlide | undefined): { hasBlocks: boolean; formatHint: string } {
	const hasBlocks = slide?.options?.some((o) => o.previewBlocks && o.previewBlocks.length > 0) ?? false;
	const formatHint = hasBlocks
		? "Use previewBlocks (array of typed blocks: html, mermaid, code, image) to match the existing options."
		: "Use previewHtml (raw HTML) or previewBlocks (array of typed blocks) to match the existing options.";
	return { hasBlocks, formatHint };
}

function optionTemplate(hasBlocks: boolean): string {
	return hasBlocks
		? JSON.stringify({
				label: "Option label",
				description: "Short rationale",
				aside: "Explanatory notes below the preview",
				previewBlocks: [{ type: "code", code: "...", lang: "ts" }],
				recommended: false,
			})
		: JSON.stringify({
				label: "Option label",
				description: "Short rationale",
				aside: "Explanatory notes below the preview",
				previewHtml: "<div class='pv-body'>...</div>",
				recommended: false,
			});
}

function modelHints(generateModel?: string, thinking?: string, action?: string): string {
	if (!generateModel) return "";
	const verb = action === "replace-options" ? "replace-options" : "add-options";
	let hint = `\nGenerate options using deck_generate({ model: "${generateModel}", task: "..." }), then push with ${verb}.`;
	if (thinking && thinking !== "off") {
		hint += `\nUse thinking level: "${thinking}".`;
	}
	return hint;
}

export function buildGenerateMoreResult(slideId: string, slide: DeckSlide | undefined, prompt?: string, generateModel?: string, thinking?: string, count: number = 1): string {
	const title = slide?.title ?? slideId;
	const context = slide?.context ? `\nContext: ${slide.context}` : "";

	const existingLines: string[] = [];
	if (slide?.options && slide.options.length > 0) {
		for (const opt of slide.options) {
			let line = `- ${opt.label}`;
			if (opt.description) line += `: ${opt.description}`;
			if (opt.aside) line += ` — ${opt.aside.split("\n")[0]}`;
			existingLines.push(line);
		}
	}
	const existingText = existingLines.length > 0 ? existingLines.join("\n") : "(none)";

	const { hasBlocks, formatHint } = formatHintForSlide(slide);
	const template = optionTemplate(hasBlocks);
	const userInstructions = prompt ? `\nUser instructions: "${prompt}"` : "";

	const optionWord = count === 1 ? "option" : "options";

	return (
		"The design deck is still open and waiting for your response.\n\n" +
		`User clicked "Generate ${count} ${optionWord}" for slide \"${title}\".${context}${userInstructions}\n\n` +
		`Existing options:\n${existingText}\n\n` +
		`YOU MUST generate ${count} distinctive additional ${optionWord} and call design_deck with add-options (one call with all options in an array). ` +
		`Do not skip this step or decide the user has enough options — they explicitly requested ${count === 1 ? "another one" : `${count} more`}.${modelHints(generateModel, thinking, "add-options")}\n\n` +
		`design_deck({\"action\":\"add-options\",\"slideId\":\"${slideId}\",\"options\":\"[${template}${count > 1 ? ", ..." : ""}]\"})` +
		`\n\nThe options field must be a JSON string containing an array of ${count} option object${count > 1 ? "s" : ""}.\n` +
		`Each option needs: label, optional description, optional aside (explanatory notes below preview), optional recommended, and either previewHtml or previewBlocks.\n` +
		`${formatHint}` +
		(count > 1 ? `\n\nMake each option distinctive — they should represent genuinely different approaches.` : "")
	);
}

export function buildRegenerateResult(slideId: string, slide: DeckSlide | undefined, optionCount: number, prompt?: string, generateModel?: string, thinking?: string): string {
	const title = slide?.title ?? slideId;
	const context = slide?.context ? `\nContext: ${slide.context}` : "";

	const { hasBlocks, formatHint } = formatHintForSlide(slide);
	const template = optionTemplate(hasBlocks);
	const userInstructions = prompt ? `\nUser instructions: "${prompt}"` : "";

	return (
		"The design deck is still open and waiting for your response.\n\n" +
		`User clicked "Regenerate all" for slide \"${title}\".${context}${userInstructions}\n\n` +
		`YOU MUST generate ${optionCount} fresh, distinctive options and call design_deck with replace-options. ` +
		`Do not skip this step — the user explicitly requested regeneration.${modelHints(generateModel, thinking, "replace-options")}\n\n` +
		`design_deck({\"action\":\"replace-options\",\"slideId\":\"${slideId}\",\"options\":\"[${template}, ...]\"})` +
		`\n\nThe options field must be a JSON string containing an array of ${optionCount} option objects.\n` +
		`Each option needs: label, optional description, optional aside, optional recommended, and either previewHtml or previewBlocks.\n` +
		`${formatHint}\n\n` +
		`Make these options substantially different from what was shown before — the user wasn't satisfied with any of them.`
	);
}

