function expandHome(value: string): string {
	if (value === "~") {
		return os.homedir();
	}
	// Handle both Unix (/) and Windows (\) separators for user convenience
	if (value.startsWith("~/") || value.startsWith("~\\")) {
		return path.join(os.homedir(), value.slice(2));
	}
	return value;
}

function resolveSnapshotDir(snapshotDir?: string): string {
	return snapshotDir ? expandHome(snapshotDir) : getDefaultSnapshotDir();
}

function escapeHtml(str: string): string {
	return str.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

function findGlimpseMjs(): string | null {
	// Local node_modules
	try {
		const req = createRequire(import.meta.url);
		return req.resolve("glimpseui");
	} catch {}
	// Global npm install
	try {
		const globalRoot = execFileSync("npm", ["root", "-g"], { encoding: "utf-8" }).trim();
		const entry = path.join(globalRoot, "glimpseui", "src", "glimpse.mjs");
		if (fs.existsSync(entry)) return entry;
	} catch {}
	return null;
}

async function getGlimpseOpen() {
	if (glimpseOpen !== undefined) return glimpseOpen;
	const resolved = findGlimpseMjs();
	if (resolved) {
		try {
			glimpseOpen = (await import(resolved)).open;
			return glimpseOpen;
		} catch {}
	}
	glimpseOpen = null;
	return glimpseOpen;
}

function openInGlimpse(
	open: (html: string, opts: Record<string, unknown>) => GlimpseWindow,
	url: string,
	title?: string,
): GlimpseWindow {
	const safeTitle = escapeHtml(title || "Design Deck");
	const shellHtml = `<!DOCTYPE html>
<html>
<head><meta charset="UTF-8"><title>${safeTitle}</title></head>
<body style="margin:0; background:#18181e;">
  <script>window.location.replace(${JSON.stringify(url)});</script>
</body>
</html>`;

	return open(shellHtml, {
		width: 1100,
		height: 800,
		title: title || "Design Deck",
	});
}

function closeActiveGlimpseWindow(): void {
	if (!activeGlimpseWin) return;
	const win = activeGlimpseWin;
	activeGlimpseWin = null;
	try {
		win.close();
	} catch {}
}

function listSavedDecks(snapshotDir: string): { decks: SavedDeckListItem[]; warnings: string[] } {
	if (!fs.existsSync(snapshotDir)) {
		return { decks: [], warnings: [] };
	}

	const entries = fs.readdirSync(snapshotDir, { withFileTypes: true });
	const decks: SavedDeckListItem[] = [];
	const warnings: string[] = [];

	for (const entry of entries) {
		if (!entry.isDirectory()) continue;
		const deckJsonPath = path.join(snapshotDir, entry.name, "deck.json");
		if (!fs.existsSync(deckJsonPath)) continue;

		try {
			const raw = JSON.parse(fs.readFileSync(deckJsonPath, "utf-8"));
			const saved = validateSavedDeck(raw);
			decks.push({
				id: saved.id ?? entry.name,
				title: saved.config.title || "Design Deck",
				savedAt: saved.savedAt,
				modifiedAt: saved.modifiedAt ?? saved.savedAt,
				status: saved.status ?? deriveDeckStatusFromFolderName(entry.name),
				...(saved.savedFrom ? { cwd: saved.savedFrom.cwd, branch: saved.savedFrom.branch } : {}),
				slideCount: saved.config.slides.length,
			});
		} catch (err) {
			const message = err instanceof Error ? err.message : String(err);
			warnings.push(`${entry.name}: ${message}`);
		}
	}

	return { decks, warnings };
}

function resolveDeckFilePath(snapshotDir: string, deckId: string): string | null {
	if (!deckId || deckId === "." || deckId === ".." || deckId.includes("/") || deckId.includes("\\")) {
		return null;
	}
	const root = path.resolve(snapshotDir);
	const deckDir = path.resolve(snapshotDir, deckId);
	if (deckDir !== root && !deckDir.startsWith(root + path.sep)) {
		return null;
	}
	return path.join(deckDir, "deck.json");
}

function buildSavedNotesForClient(saved: SavedDeckData): Record<string, { label: string; notes: string }> | undefined {
	const savedNotesForClient: Record<string, { label: string; notes: string }> = {};
	for (const [slideId, noteString] of Object.entries(saved.notes ?? {})) {
		const label = saved.selections[slideId];
		if (label && noteString) {
			savedNotesForClient[slideId] = { label, notes: noteString };
		}
	}
	return Object.keys(savedNotesForClient).length > 0 ? savedNotesForClient : undefined;
}

function loadDeckFile(absolutePath: string): LoadedDeckSource {
	const content = fs.readFileSync(absolutePath, "utf-8");
	let fileData: unknown;
	try {
		fileData = JSON.parse(content);
	} catch (parseErr) {
		const message = parseErr instanceof Error ? parseErr.message : String(parseErr);
		throw new Error(`Invalid JSON in saved deck file: ${message}`);
	}

	const raw = fileData as Record<string, unknown>;
	if (raw.config && typeof raw.config === "object") {
		const saved = validateSavedDeck(fileData);
		const snapshotDir = path.dirname(absolutePath);
		for (const slide of saved.config.slides) {
			for (const option of slide.options) {
				if (!option.previewBlocks) continue;
				for (const block of option.previewBlocks) {
					if (block.type === "image" && !path.isAbsolute(block.src)) {
						block.src = path.join(snapshotDir, block.src);
					}
				}
			}
		}
		const savedNotes = buildSavedNotesForClient(saved);
		return {
			configData: saved.config,
			...(Object.keys(saved.selections).length > 0 ? { savedSelections: saved.selections } : {}),
			...(savedNotes !== undefined ? { savedNotes } : {}),
			...(saved.finalNotes !== undefined ? { savedFinalNotes: saved.finalNotes } : {}),
		};
	}

	return { configData: fileData };
}

const DEFAULT_THEME_HOTKEY = "mod+shift+l";

function clearDeckIdleTimer(): void {
	if (activeDeckIdleTimer) {
		clearTimeout(activeDeckIdleTimer);
		activeDeckIdleTimer = null;
	}
}

function cleanupActiveDeck(reason?: string): void {
	clearDeckIdleTimer();
	if (restoreDeckThinking) {
		restoreDeckThinking();
		restoreDeckThinking = null;
	}
	closeActiveGlimpseWindow();
	if (!activeDeckServer) return;
	try {
		activeDeckServer.handle.close(reason);
	} catch {}
	activeDeckServer = null;
}

function cleanupActiveDeckAndStoreResult(result: DeckToolResult): void {
	if (!activeDeckServer) return;
	// Extract close reason from result details
	const details = result.details as DeckDetails | undefined;
	const closeReason = details?.status === "aborted" ? "aborted" : details?.reason;
	if (activeDeckServer.currentResolve) {
		const resolve = activeDeckServer.currentResolve;
		cleanupActiveDeck(closeReason);
		resolve(result);
	} else {
		pendingDeckResult = result;
		cleanupActiveDeck(closeReason);
	}
}

function armDeckIdleTimer(): void {
	clearDeckIdleTimer();
	activeDeckIdleTimer = setTimeout(() => {
		if (!activeDeckServer) return;
		const url = activeDeckServer.handle.url;
		cleanupActiveDeckAndStoreResult({
			content: [{ type: "text", text: "Design deck closed after 5 minutes of inactivity." }],
			details: { status: "cancelled", url, reason: "idle-timeout" },
		});
	}, DECK_IDLE_TIMEOUT_MS);
}

function blockOnDeck(): Promise<DeckToolResult> {
	if (!activeDeckServer) {
		return Promise.resolve({
			content: [{ type: "text", text: "No active design deck session." }],
			details: { status: "error", url: "" },
		});
	}
	clearDeckIdleTimer();
	return new Promise((resolve) => {
		activeDeckServer!.currentResolve = resolve;
	});
}

function attachDeckAbortHandler(signal: AbortSignal | undefined): void {
	if (!signal) return;
	const abortHandler = () => {
		if (!activeDeckServer) return;
		const url = activeDeckServer.handle.url;
		cleanupActiveDeckAndStoreResult({
			content: [{ type: "text", text: "Design deck was aborted." }],
			details: { status: "aborted", url },
		});
	};
	signal.addEventListener("abort", abortHandler, { once: true });
}

function formatDeckSelections(selections: Record<string, string>, notes?: Record<string, string>): string {
	const entries = Object.entries(selections);
	if (entries.length === 0) return "(none)";
	return entries.map(([key, value]) => {
		const note = notes?.[key];
		if (note) {
			return `- ${key}: ${value}\n  Notes: ${note}`;
		}
		return `- ${key}: ${value}`;
	}).join("\n");
}

export default function (pi: ExtensionAPI) {

	pi.registerTool({
		name: "design_deck",
		label: "Design Deck",
		description:
			"Present a multi-slide design deck with visual options for decisions. " +
			"On macOS, opens in a native window (Glimpse); falls back to a browser tab elsewhere. " +
			"Slides JSON: { title?, slides: [{ id, title, context?, columns?, options }] }. " +
			"When the user requests more options, tool returns generate-more instructions — " +
			'call design_deck with action:"add-options" to push all new options at once. ' +
			"previewBlocks for code/architecture comparisons, previewHtml for custom UI mockups.",
		promptSnippet:
			"Use this to present architecture/UI/code choices visually. Start with {slides: <deck-json-string>} and wait for completion. " +
			"If it returns generate-more instructions, call design_deck with action:\"add-options\" and slideId to push all new options.",
		parameters: DeckParams,

		async execute(_toolCallId, params, signal, onUpdate, ctx) {
			const p = params as Record<string, unknown>;

			if (!p.action && typeof p.slides === "string") {
				try {
					const parsed = JSON.parse(p.slides);
					if (parsed && typeof parsed === "object" && !Array.isArray(parsed) && typeof parsed.action === "string") {
						Object.assign(p, parsed);
						delete p.slides;
					}
				} catch {}
			}

			if (!ctx.hasUI && p.action !== "list" && p.action !== "export") {
				throw new Error(
					"design_deck requires interactive mode with browser support. " +
						"Cannot run in headless/RPC/print mode."
				);
			}

			if (p.action === "list") {
				const settings = loadSettings();
				const snapshotDir = resolveSnapshotDir(settings.snapshotDir);
				const { decks, warnings } = listSavedDecks(snapshotDir);
				const content: Array<{ type: "text"; text: string }> = [
					{ type: "text", text: JSON.stringify(decks, null, 2) },
				];
				if (warnings.length > 0) {
					content.push({ type: "text", text: `Warnings:\n${warnings.map((w) => `- ${w}`).join("\n")}` });
				}
				return { content, details: { status: "completed", url: "" } };
			}

			if (p.action === "add-option") {
				if (typeof p.slideId !== "string" || p.slideId.trim() === "") {
					activeDeckServer?.handle.cancelGenerate();
					return {
						content: [{ type: "text", text: 'add-option requires slideId (string). Example: { action: "add-option", slideId: "arch", option: "<JSON string>" }' }],
						details: { status: "error", url: activeDeckServer?.handle.url ?? "" },
					};
				}
				if (typeof p.option !== "string" || p.option.trim() === "") {
					activeDeckServer?.handle.cancelGenerate();
					return {
						content: [{ type: "text", text: 'add-option requires option (JSON string with label and either previewHtml or previewBlocks).' }],
						details: { status: "error", url: activeDeckServer?.handle.url ?? "" },
					};
				}
			} else if (p.action === "add-options") {
				if (typeof p.slideId !== "string" || p.slideId.trim() === "") {
					activeDeckServer?.handle.cancelGenerate();
					return {
						content: [{ type: "text", text: 'add-options requires slideId (string).' }],
						details: { status: "error", url: activeDeckServer?.handle.url ?? "" },
					};
				}
				if (typeof p.options !== "string" || p.options.trim() === "") {
					activeDeckServer?.handle.cancelGenerate();
					return {
						content: [{ type: "text", text: 'add-options requires options (JSON array string).' }],
						details: { status: "error", url: activeDeckServer?.handle.url ?? "" },
					};
				}
			} else if (p.action === "replace-options") {
				if (typeof p.slideId !== "string" || p.slideId.trim() === "") {
					activeDeckServer?.handle.cancelGenerate();
					return {
						content: [{ type: "text", text: 'replace-options requires slideId (string).' }],
						details: { status: "error", url: activeDeckServer?.handle.url ?? "" },
					};
				}
				if (typeof p.options !== "string" || p.options.trim() === "") {
					activeDeckServer?.handle.cancelGenerate();
					return {
						content: [{ type: "text", text: 'replace-options requires options (JSON array string).' }],
						details: { status: "error", url: activeDeckServer?.handle.url ?? "" },
					};
				}
			} else if (p.action === "open" || p.action === "export") {
				if (typeof p.deckId !== "string" || p.deckId.trim() === "") {
					return {
						content: [{ type: "text", text: `${p.action} requires deckId (string). Example: { action: "${p.action}", deckId: "tabs-component-myapp-main-2026-03-01-103045-submitted" }` }],
						details: { status: "error", url: activeDeckServer?.handle.url ?? "" },
					};
				}
			} else if (typeof p.slides !== "string" || p.slides.trim() === "") {
				return {
					content: [{
						type: "text",
						text:
							"design_deck requires one of:\n\n" +
							'1. Start a new deck: { slides: "<JSON string of { title?, slides: [{ id, title, options }] }>" }\n' +
							'2. Open a saved deck: { action: "open", deckId: "..." }\n' +
							'3. Export a saved deck: { action: "export", deckId: "...", format: "html" }\n' +
							'4. Add options to running deck: { action: "add-options", slideId: "...", options: "[<JSON array>]" }\n' +
							'5. Add single option: { action: "add-option", slideId: "...", option: "<JSON string>" }\n\n' +
							"Each option needs label + either previewHtml (raw HTML) or previewBlocks (array of {type, ...} blocks).\n" +
							"Block types: html, mermaid, code, image.",
					}],
					details: { status: "error", url: "" },
				};
			}

			if (p.action === "add-option") {
				if (pendingDeckResult) {
					const result = pendingDeckResult;
					pendingDeckResult = null;
					return result;
				}

				if (!activeDeckServer) {
					return {
						content: [
							{
								type: "text",
								text: "No active design deck session. Start a new deck before adding options.",
							},
						],
						details: { status: "error", url: "" },
					};
				}

				// Note: We don't check currentResolve here because multiple parallel
				// add-option calls are valid (e.g., user requests 3 options at once)

				const slideId = p.slideId as string;
				const option = p.option as string;

				let parsedOption: unknown;
				try {
					parsedOption = JSON.parse(option);
				} catch (err) {
					activeDeckServer.handle.cancelGenerate();
					const message = err instanceof Error ? err.message : String(err);
					const snippet = option.length > 300 ? option.slice(0, 300) + "..." : option;
					return {
						content: [{ type: "text", text: `Invalid option JSON: ${message}\n\nReceived:\n${snippet}\n\nFix the JSON and call design_deck add-option again.` }],
						details: { status: "error", url: activeDeckServer.handle.url },
					};
				}

				if (!isDeckOption(parsedOption)) {
					activeDeckServer.handle.cancelGenerate();
					return {
						content: [{ type: "text", text: "Option is invalid — needs label (string) and either previewHtml (non-empty string) or previewBlocks (non-empty array). Fix and call design_deck add-option again." }],
						details: { status: "error", url: activeDeckServer.handle.url },
					};
				}

				try {
					activeDeckServer.handle.pushOption(slideId, parsedOption);
				} catch (err) {
					const message = err instanceof Error ? err.message : String(err);
					return {
						content: [{ type: "text", text: `Failed to push option: ${message}` }],
						details: { status: "error", url: activeDeckServer.handle.url },
					};
				}

				// For add-option, return immediately without blocking.
				// This allows parallel add-option calls to all succeed.
				// The deck stays open and will send a new prompt when the user
				// clicks generate-more again or submits.
				return {
					content: [{ type: "text", text: `Pushed option "${parsedOption.label}" to slide ${slideId}.` }],
					details: { status: "generate-more", url: activeDeckServer.handle.url, slideId },
				};
			}

			if (p.action === "add-options") {
				if (pendingDeckResult) {
					const result = pendingDeckResult;
					pendingDeckResult = null;
					return result;
				}

				if (!activeDeckServer) {
					return {
						content: [{ type: "text", text: "No active design deck session. Start a new deck before adding options." }],
						details: { status: "error", url: "" },
					};
				}

				if (activeDeckServer.currentResolve !== null) {
					return {
						content: [{ type: "text", text: "Design deck is not waiting for new options right now." }],
						details: { status: "error", url: activeDeckServer.handle.url },
					};
				}

				const slideId = p.slideId as string;
				const optionsStr = p.options as string;

				let parsedOptions: unknown;
				try {
					parsedOptions = JSON.parse(optionsStr);
				} catch (err) {
					activeDeckServer.handle.cancelGenerate();
					const message = err instanceof Error ? err.message : String(err);
					const snippet = optionsStr.length > 300 ? optionsStr.slice(0, 300) + "..." : optionsStr;
					return {
						content: [{ type: "text", text: `Invalid options JSON: ${message}\n\nReceived:\n${snippet}\n\nFix the JSON and call design_deck add-options again.` }],
						details: { status: "error", url: activeDeckServer.handle.url },
					};
				}

				if (!Array.isArray(parsedOptions)) {
					activeDeckServer.handle.cancelGenerate();
					return {
						content: [{ type: "text", text: "options must be a JSON array of deck options. Fix and call design_deck add-options again." }],
						details: { status: "error", url: activeDeckServer.handle.url },
					};
				}

				for (const opt of parsedOptions) {
					if (!isDeckOption(opt)) {
						activeDeckServer.handle.cancelGenerate();
						return {
							content: [{ type: "text", text: "One or more options in the array are invalid — each needs label and either previewHtml or previewBlocks. Fix and call design_deck add-options again." }],
							details: { status: "error", url: activeDeckServer.handle.url },
						};
					}
				}

				try {
					for (const opt of parsedOptions) {
						activeDeckServer.handle.pushOption(slideId, opt);
					}
				} catch (err) {
					const message = err instanceof Error ? err.message : String(err);
					return {
						content: [{ type: "text", text: `Failed to push options: ${message}` }],
						details: { status: "error", url: activeDeckServer.handle.url },
					};
				}

				if (onUpdate) {
					onUpdate({
						content: [{ type: "text", text: `Pushed ${parsedOptions.length} options to slide ${slideId}.` }],
						details: { status: "generate-more", url: activeDeckServer.handle.url, slideId },
					});
				}
				attachDeckAbortHandler(signal);
				return blockOnDeck();
			}

			if (p.action === "replace-options") {
				if (pendingDeckResult) {
					const result = pendingDeckResult;
					pendingDeckResult = null;
					return result;
				}

				if (!activeDeckServer) {
					return {
						content: [{ type: "text", text: "No active design deck session. Start a new deck before replacing options." }],
						details: { status: "error", url: "" },
					};
				}

				if (activeDeckServer.currentResolve !== null) {
					return {
						content: [{ type: "text", text: "Design deck is not waiting for regenerated options right now." }],
						details: { status: "error", url: activeDeckServer.handle.url },
					};
				}

				const slideId = p.slideId as string;
				const optionsStr = p.options as string;

				let parsedOptions: unknown;
				try {
					parsedOptions = JSON.parse(optionsStr);
				} catch (err) {
					activeDeckServer.handle.cancelGenerate();
					const message = err instanceof Error ? err.message : String(err);
					const snippet = optionsStr.length > 300 ? optionsStr.slice(0, 300) + "..." : optionsStr;
					return {
						content: [{ type: "text", text: `Invalid options JSON: ${message}\n\nReceived:\n${snippet}\n\nFix the JSON and call design_deck replace-options again.` }],
						details: { status: "error", url: activeDeckServer.handle.url },
					};
				}

				if (!Array.isArray(parsedOptions)) {
					activeDeckServer.handle.cancelGenerate();
					return {
						content: [{ type: "text", text: "options must be a JSON array of deck options. Fix and call design_deck replace-options again." }],
						details: { status: "error", url: activeDeckServer.handle.url },
					};
				}

				for (const opt of parsedOptions) {
					if (!isDeckOption(opt)) {
						activeDeckServer.handle.cancelGenerate();
						return {
							content: [{ type: "text", text: "One or more options in the array are invalid — each needs label and either previewHtml or previewBlocks. Fix and call design_deck replace-options again." }],
							details: { status: "error", url: activeDeckServer.handle.url },
						};
					}
				}

				try {
					activeDeckServer.handle.replaceSlideOptions(slideId, parsedOptions);
				} catch (err) {
					const message = err instanceof Error ? err.message : String(err);
					return {
						content: [{ type: "text", text: `Failed to replace options: ${message}` }],
						details: { status: "error", url: activeDeckServer.handle.url },
					};
				}

				if (onUpdate) {
					onUpdate({
						content: [{ type: "text", text: `Replaced ${parsedOptions.length} options for slide ${slideId}.` }],
						details: { status: "generate-more", url: activeDeckServer.handle.url, slideId },
					});
				}
				attachDeckAbortHandler(signal);
				return blockOnDeck();
			}

			pendingDeckResult = null;

			if (activeDeckServer && p.action !== "export") {
				return {
					content: [
						{
							type: "text",
							text: "A design deck is already active. Complete or cancel it before starting another.",
						},
					],
					details: { status: "error", url: activeDeckServer.handle.url },
				};
			}

			const settings = loadSettings();
			const snapshotDir = resolveSnapshotDir(settings.snapshotDir);
			let slides = p.slides as string;
			if (p.action === "open" || p.action === "export") {
				const deckId = (p.deckId as string).trim();
				const deckPath = resolveDeckFilePath(snapshotDir, deckId);
				if (!deckPath || !fs.existsSync(deckPath)) {
					const { decks } = listSavedDecks(snapshotDir);
					const availableHint = decks.length > 0
						? ` Available deck IDs: ${decks.slice(0, 10).map((deck) => deck.id).join(", ")}`
						: " Snapshot directory is empty.";
					return {
						content: [{ type: "text", text: `Saved deck "${deckId}" not found in ${snapshotDir}.${availableHint}` }],
						details: { status: "error", url: "" },
					};
				}
				if (p.action === "export") {
					const format = typeof p.format === "string" && p.format.trim() !== "" ? p.format.trim().toLowerCase() : "html";
					if (format !== "html") {
						return {
							content: [{ type: "text", text: `Unsupported export format: ${format}` }],
							details: { status: "error", url: "" },
						};
					}
					try {
						const saved = validateSavedDeck(JSON.parse(fs.readFileSync(deckPath, "utf-8")));
						const enrichedSaved: SavedDeckData = {
							...saved,
							id: saved.id ?? deckId,
							status: saved.status ?? deriveDeckStatusFromFolderName(deckId),
						};
						const html = buildStandaloneDeckHtml(deckPath, enrichedSaved);
						const exportPath = path.join(path.dirname(deckPath), "export.html");
						fs.writeFileSync(exportPath, html, "utf-8");
						const relativePath = exportPath.startsWith(os.homedir())
							? "~" + exportPath.slice(os.homedir().length)
							: exportPath;
						return {
							content: [{ type: "text", text: `Exported HTML to ${relativePath}` }],
							details: { status: "completed", url: "" },
						};
					} catch (err) {
						const message = err instanceof Error ? err.message : String(err);
						return {
							content: [{ type: "text", text: `Failed to export deck "${deckId}": ${message}` }],
							details: { status: "error", url: "" },
						};
					}
				}
				slides = deckPath;
			}

			let configData: unknown;
			let savedSelections: Record<string, string> | undefined;
			let savedNotes: Record<string, { label: string; notes: string }> | undefined;
			let savedFinalNotes: string | undefined;
			try {
				configData = JSON.parse(slides);
			} catch {
				const expanded = expandHome(slides);
				const absolutePath = path.isAbsolute(expanded) ? expanded : path.join(ctx.cwd, slides);
				if (!fs.existsSync(absolutePath)) {
					throw new Error(`Invalid slides: not valid JSON and file not found at ${absolutePath}`);
				}
				const loaded = loadDeckFile(absolutePath);
				configData = loaded.configData;
				savedSelections = loaded.savedSelections;
				savedNotes = loaded.savedNotes;
				savedFinalNotes = loaded.savedFinalNotes;
			}
			const config = validateDeckConfig(configData);
			const sessionId = randomUUID();
			const sessionToken = [REDACTED];

			if (signal?.aborted) {
				return {
					content: [{ type: "text", text: "Design deck was aborted." }],
					details: { status: "aborted", url: "" },
				};
			}

			const handleSubmit = (selections: Record<string, string>, notes?: Record<string, string>, finalNotes?: string) => {
				if (!activeDeckServer) return;
				const url = activeDeckServer.handle.url;
				const hasNotes = notes && Object.keys(notes).length > 0;
				const textParts = [`Design deck completed.\n\nSelections:\n${formatDeckSelections(selections, notes)}`];
				if (finalNotes) {
					textParts.push(`\nAdditional instructions:\n${finalNotes}`);
				}
				cleanupActiveDeckAndStoreResult({
					content: [
						{
							type: "text",
							text: textParts.join(""),
						},
					],
					details: { 
						status: "completed", 
						url, 
						selections, 
						...(hasNotes ? { notes } : {}),
						...(finalNotes ? { finalNotes } : {}),
					},
				});
			};

			const handleCancel = (reason?: "user" | "stale" | "aborted") => {
				if (!activeDeckServer) return;
				const url = activeDeckServer.handle.url;
				cleanupActiveDeckAndStoreResult({
					content: [
						{
							type: "text",
							text:
								reason === "stale"
									? "Design deck session ended due to lost heartbeat."
									: "Design deck was cancelled.",
						},
					],
					details: { status: "cancelled", url, ...(reason !== undefined ? { reason } : {}) },
				});
			};

			const handleGenerateMore = (slideId: string, prompt?: string, model?: string, thinking?: string, count?: number) => {
				if (!activeDeckServer?.currentResolve) {
					// Agent is no longer listening - close the deck
					cleanupActiveDeck("stale");
					return;
				}
				const resolve = activeDeckServer.currentResolve;
				activeDeckServer.currentResolve = null;
				armDeckIdleTimer();
				const slide = config.slides.find((s) => s.id === slideId);
				const effectiveModel = model === undefined ? loadSettings().generateModel : (model || undefined);
				if (thinking && !effectiveModel) {
					pi.setThinkingLevel(thinking as "off" | "minimal" | "low" | "medium" | "high" | "xhigh");
				}
				const effectiveCount = count && count >= 1 && count <= 5 ? count : 1;
				resolve({
					content: [{ type: "text", text: buildGenerateMoreResult(slideId, slide, prompt, effectiveModel, thinking, effectiveCount) }],
					details: {
						status: "generate-more",
						url: activeDeckServer.handle.url,
						slideId,
					},
				});
			};

			const handleRegenerateSlide = (slideId: string, prompt?: string, model?: string, thinking?: string) => {
				if (!activeDeckServer?.currentResolve) {
					// Agent is no longer listening - close the deck
					cleanupActiveDeck("stale");
					return;
				}
				const resolve = activeDeckServer.currentResolve;
				activeDeckServer.currentResolve = null;
				armDeckIdleTimer();
				const slide = config.slides.find((s) => s.id === slideId);
				const optionCount = slide?.options?.length || 2;
				const effectiveModel = model === undefined ? loadSettings().generateModel : (model || undefined);
				if (thinking && !effectiveModel) {
					pi.setThinkingLevel(thinking as "off" | "minimal" | "low" | "medium" | "high" | "xhigh");
				}
				resolve({
					content: [{ type: "text", text: buildRegenerateResult(slideId, slide, optionCount, prompt, effectiveModel, thinking) }],
					details: {
						status: "generate-more",
						url: activeDeckServer.handle.url,
						slideId,
					},
				});
			};

			const themeConfig = settings.theme ?? {};
			const currentModelStr = ctx.model ? `${ctx.model.provider}/${ctx.model.id}` : null;
			const availableModels: ModelInfo[] = ctx.modelRegistry.getAvailable().map((m) => ({
				provider: m.provider,
				id: m.id,
				name: m.name,
				reasoning: m.reasoning,
			}));

			const originalThinking = pi.getThinkingLevel();
			restoreDeckThinking = () => pi.setThinkingLevel(originalThinking);

			const serverHandle = await startDeckServer(
				{
					config,
					sessionToken,
					sessionId,
					cwd: ctx.cwd,
					...(settings.port !== undefined ? { port: settings.port } : {}),
					theme: {
						mode: themeConfig.mode ?? "dark",
						toggleHotkey: themeConfig.toggleHotkey ?? DEFAULT_THEME_HOTKEY,
					},
					...(savedSelections !== undefined ? { savedSelections } : {}),
					...(savedNotes !== undefined ? { savedNotes } : {}),
					...(savedFinalNotes !== undefined ? { savedFinalNotes } : {}),
					snapshotDir,
					autoSaveOnSubmit: settings.autoSaveOnSubmit ?? true,
					models: {
						current: currentModelStr,
						available: availableModels,
						defaultModel: settings.generateModel ?? null,
						currentThinking: originalThinking,
						currentModelReasoning: ctx.model?.reasoning ?? false,
					},
				},
				{
					onSubmit: handleSubmit,
					onCancel: handleCancel,
					onGenerateMore: handleGenerateMore,
					onRegenerateSlide: handleRegenerateSlide,
				}
			);

			activeDeckServer = { handle: serverHandle, currentResolve: null };
			attachDeckAbortHandler(signal);

			if (onUpdate) {
				onUpdate({
					content: [{ type: "text", text: "Design deck server started." }],
					details: { status: "generate-more", url: serverHandle.url },
				});
			}

			const remoteLikely = isRemoteSession() || await hasActiveRemoteLogin();
			const emitRemoteHint = async (outcome: BrowserOpenOutcome): Promise<void> => {
				if (!onUpdate) return;
				const hint = remoteAccessHint({
					url: serverHandle.url,
					port: serverHandle.port,
					moshi: await probeMoshiGateway(),
					outcome,
				});
				onUpdate({
					content: [{ type: "text", text: hint }],
					details: { status: "generate-more", url: serverHandle.url },
				});
			};

			const glimpseOpenFn = os.platform() === "darwin" && !isRemoteSession() ? await getGlimpseOpen() : null;
			if (glimpseOpenFn) {
				try {
					const thisWindow = openInGlimpse(glimpseOpenFn, serverHandle.url, config.title || "Design Deck");
					activeGlimpseWin = thisWindow;
					thisWindow.on("error", () => {});
					thisWindow.on("closed", () => {
						if (activeGlimpseWin !== thisWindow) return;
						activeGlimpseWin = null;
						handleCancel("user");
					});
					if (remoteLikely) {
						await emitRemoteHint({ status: "opened-on-host" });
					}
				} catch {}
			}

			if (!activeGlimpseWin) {
				let openOutcome: BrowserOpenOutcome = { status: "opened-on-host" };
				try {
					await openUrl(pi, serverHandle.url, settings.browser);
				} catch (err) {
					openOutcome = {
						status: "failed",
						error: err instanceof Error ? err.message : String(err),
					};
				}
				// On macOS/Windows hosts `open`/`start` succeeds over ssh but opens on the
				// host's own display, so a remote-looking session also receives the hint.
				if (openOutcome.status === "failed" || remoteLikely) {
					await emitRemoteHint(openOutcome);
				}
			}

			return blockOnDeck();
		},

		renderCall(args, theme) {
			const data = args as { action?: string; slideId?: string; slides?: string };
			if (data.action === "add-option") {
				return new Text(
					theme.fg("toolTitle", theme.bold(`Design Deck: add option (${data.slideId || "unknown"})`)),
					0,
					0
				);
			}
			if (data.action === "add-options") {
				return new Text(
					theme.fg("toolTitle", theme.bold(`Design Deck: add options (${data.slideId || "unknown"})`)),
					0,
					0
				);
			}
			if (data.action === "replace-options") {
				return new Text(
					theme.fg("toolTitle", theme.bold(`Design Deck: replace options (${data.slideId || "unknown"})`)),
					0,
					0
				);
			}
			if (typeof data.slides === "string" && data.slides.trim()) {
				try {
					const parsed = JSON.parse(data.slides) as { slides?: unknown[] };
					if (Array.isArray(parsed.slides)) {
						return new Text(theme.fg("toolTitle", theme.bold(`Design Deck: ${parsed.slides.length} slides`)), 0, 0);
					}
				} catch {
					// JSON incomplete during streaming - fall through
				}
			}
			return new Text(theme.fg("toolTitle", theme.bold("Design Deck")), 0, 0);
		},

		renderResult(result, _options, theme) {
			const details = result.details as DeckDetails | undefined;
			if (!details) return new Text("Design Deck", 0, 0);

			if (details.status === "generate-more") {
				const slide = details.slideId ? ` (${details.slideId})` : "";
				return new Text(theme.fg("warning", `GENERATE-MORE${slide}`), 0, 0);
			}

			if (details.status === "completed") {
				const count = details.selections ? Object.keys(details.selections).length : 0;
				return new Text(theme.fg("success", `COMPLETED (${count} selections)`), 0, 0);
			}

			if (details.status === "cancelled") {
				const reason = details.reason ? ` (${details.reason})` : "";
				return new Text(theme.fg("warning", `CANCELLED${reason}`), 0, 0);
			}

			if (details.status === "aborted") {
				return new Text(theme.fg("error", "ABORTED"), 0, 0);
			}

			return new Text(theme.fg("error", "ERROR"), 0, 0);
		},
	});

	pi.registerTool({
		name: "deck_generate",
		label: "Deck Generate",
		description: "Generate text using a specific model (for design deck option generation). Use this when the generate-more prompt specifies a model override.",
		promptSnippet:
			"Use when design_deck generate-more/regenerate asks for a specific model. Provide {model: \"provider/model-id\", task: \"prompt\"} and return the raw generated text.",
		parameters: Type.Object({
			model: Type.String({ description: "Full model ID in 'provider/model-id' format (e.g., 'anthropic/claude-haiku-4-5')" }),
			task: Type.String({ description: "The generation task/prompt" }),
		}),
		async execute(_toolCallId, params) {
			const { model, task } = params as { model: string; task: string };
			try {
				const result = await generateWithModel(model, task);
				return { content: [{ type: "text", text: result }], details: {} };
			} catch (err) {
				const message = err instanceof Error ? err.message : String(err);
				return { content: [{ type: "text", text: `Generation failed: ${message}` }], details: {}, isError: true };
			}
		},
	});

	pi.on("session_shutdown", () => {
		pendingDeckResult = null;
		cleanupActiveDeck();
	});
}

// ─── SELECTION ───────────────────────────────────────────────

function applySavedSelections(savedSelections, savedNotes) {
	if (!savedSelections || typeof savedSelections !== "object") return;
	isRestoringSelections = true;
	try {
		for (const [slideId, label] of Object.entries(savedSelections)) {
			if (typeof label !== "string") continue;
			const slideEl = document.querySelector(`.slide[data-id="${CSS.escape(slideId)}"]`);
			if (!slideEl) continue;
			for (const card of slideEl.querySelectorAll(".option")) {
				if (card.dataset.value === label) {
					selectOption(card);
					break;
				}
			}
		}
	} finally {
		isRestoringSelections = false;
	}
	// Restore notes
	if (savedNotes && typeof savedNotes === "object") {
		for (const [slideId, noteData] of Object.entries(savedNotes)) {
			if (noteData && typeof noteData === "object" && noteData.label && noteData.notes) {
				optionNotes[slideId] = noteData;
				// Find and populate the textarea
				const input = document.querySelector(`.option-notes-input[data-slide-id="${CSS.escape(slideId)}"][data-option-label="${CSS.escape(noteData.label)}"]`);
				if (input) input.value = noteData.notes;
			}
		}
	}
}

function restoreSelections() {
	const serverSaved = deckData.savedSelections;
	const hasServerSavedSelections = serverSaved && typeof serverSaved === "object" && Object.keys(serverSaved).length > 0;
	const hasServerSavedNotes = deckData.savedNotes && typeof deckData.savedNotes === "object" && Object.keys(deckData.savedNotes).length > 0;
	const hasServerFinalNotes = typeof deckData.savedFinalNotes === "string" && deckData.savedFinalNotes.trim() !== "";
	if (hasServerSavedSelections || hasServerSavedNotes || hasServerFinalNotes) {
		applySavedSelections(hasServerSavedSelections ? serverSaved : null, deckData.savedNotes || null);
		if (deckData.savedFinalNotes) {
			finalNotes = deckData.savedFinalNotes;
			const input = document.getElementById("final-notes-input");
			if (input) input.value = deckData.savedFinalNotes;
		}
		return;
	}
	const stored = loadSelectionsFromStorage();
	if (stored) {
		applySavedSelections(stored.selections || stored, stored.optionNotes);
		// Restore final notes if present
		if (stored.finalNotes) {
			finalNotes = stored.finalNotes;
			const input = document.getElementById("final-notes-input");
			if (input) input.value = stored.finalNotes;
		}
	}
}

function applySelectionClasses(slideElement, selectedElement) {
	slideElement.querySelectorAll(".option").forEach((optionEl) => {
		optionEl.classList.remove("selected");
		optionEl.setAttribute("aria-checked", "false");
	});
	selectedElement.classList.add("selected");
	selectedElement.setAttribute("aria-checked", "true");
}

function selectOption(optionElement) {
	if (isClosed) return;
	const slideElement = optionElement.closest(".slide");
	if (!slideElement) return;
	const slideId = slideElement.dataset.id;
	if (!slideId || slideId === "summary") return;
	const nextValue = optionElement.dataset.value || "";
	if (selections[slideId] === nextValue) return;

	applySelectionClasses(slideElement, optionElement);
	selections[slideId] = nextValue;
	if (!isRestoringSelections) {
		saveSelectionsToStorage();
		markDirty();
	}
}

// ─── NAVIGATION ──────────────────────────────────────────────

function showSlide(index) {
	if (index < 0 || index >= totalSlides) return;
	const previousSlide = slidesWrap.children[current];
	const activeSlide = slidesWrap.children[index];
	current = index;

	if (previousSlide !== activeSlide) previousSlide?.classList.remove("active");
	activeSlide?.classList.add("active");

	if (progressFill) {
		progressFill.style.width = `${((index + 1) / totalSlides) * 100}%`;
	}

	if (btnBack) {
		btnBack.disabled = index === 0 || isClosed;
	}

	if (btnNext) {
		if (index === totalSlides - 1) {
			btnNext.textContent = "Done";
			btnNext.disabled = true;
		} else {
			btnNext.textContent = "Next \u2192";
			btnNext.disabled = isClosed;
		}
	}

	if (index === totalSlides - 1) {
		updateSummary();
	}

	if (activeSlide) {
		equalizeBlockHeights(activeSlide);
		const heading = activeSlide.querySelector("h2");
		if (heading) heading.focus({ preventScroll: true });
	}
}

function moveFocusInRadiogroup(direction) {
	const activeSlide = document.querySelector(".slide.active");
	if (!activeSlide || activeSlide.dataset.id === "summary") return false;

	const options = Array.from(activeSlide.querySelectorAll(".option"));
	if (options.length === 0) return false;

	const currentFocus = document.activeElement;
	const currentIndex = options.indexOf(currentFocus);
	if (currentIndex === -1) return false;

	let nextIndex = currentIndex + direction;
	if (nextIndex < 0) nextIndex = options.length - 1;
	if (nextIndex >= options.length) nextIndex = 0;

	options[nextIndex].focus();
	return true;
}

function navigate(direction) {
	if (isClosed) return;
	const next = current + direction;
	if (next < 0 || next >= totalSlides) return;
	showSlide(next);
}

// ─── KEYBOARD HANDLING ───────────────────────────────────────

function handleKeydown(event) {
	if (isClosed) return;

	if (event.key === "ArrowDown" || event.key === "ArrowRight") {
		const isInRadiogroup = document.activeElement && document.activeElement.classList.contains("option");
		if (isInRadiogroup) {
			event.preventDefault();
			moveFocusInRadiogroup(1);
			return;
		}
		event.preventDefault();
		navigate(1);
		return;
	}

	if (event.key === "ArrowUp" || event.key === "ArrowLeft") {
		const isInRadiogroup = document.activeElement && document.activeElement.classList.contains("option");
		if (isInRadiogroup) {
			event.preventDefault();
			moveFocusInRadiogroup(-1);
			return;
		}
		event.preventDefault();
		navigate(-1);
		return;
	}

	if (event.key === " ") {
		const focused = document.activeElement;
		if (focused && focused.classList.contains("option")) {
			event.preventDefault();
			selectOption(focused);
			return;
		}
	}

	if (event.key === "Enter") {
		const focused = document.activeElement;
		if (focused && focused.classList.contains("option")) {
			event.preventDefault();
			selectOption(focused);
			return;
		}
		if (focused && focused.tagName === "BUTTON") {
			return;
		}
		event.preventDefault();
		if (current === totalSlides - 1) {
			submitDeck().catch(() => {});
		} else {
			navigate(1);
		}
		return;
	}

	if (event.key === "Escape") {
		event.preventDefault();
		handleEscape();
		return;
	}

	const num = Number.parseInt(event.key, 10);
	if (Number.isNaN(num) || num < 1 || num > 9) return;

	const activeSlide = document.querySelector(".slide.active");
	if (!activeSlide || activeSlide.dataset.id === "summary") return;

	const options = activeSlide.querySelectorAll(".option");
	const target = options[num - 1];
	if (target) {
		event.preventDefault();
		selectOption(target);
	}
}

// ─── MODEL BAR ───────────────────────────────────────────────

async function fetchModels() {
	try {
		const res = await fetch(`/models?session=${encodeURIComponent(sessionToken)}`);
		if (!res.ok) return null;
		return await res.json();
	} catch {
		return null;
	}
}

function modelSupportsXhigh(id) {
	return id.includes("gpt-5.2") || id.includes("gpt-5.3") ||
		id.includes("opus-4-6") || id.includes("opus-4.6");
}

function renderThinkingPills(container, modelId) {
	container.innerHTML = "";
	const levels = ["off", "low", "medium", "high"];
	if (modelSupportsXhigh(modelId)) levels.push("xhigh");
	const labels = { off: "off", low: "low", medium: "med", high: "high", xhigh: "xhigh" };
	for (const level of levels) {
		const pill = document.createElement("button");
		pill.type = "button";
		pill.className = "model-pill" + (selectedThinking === level ? " active" : "");
		pill.dataset.level = level;
		pill.textContent = labels[level] || level;
		pill.addEventListener("click", () => {
			selectedThinking = level;
			container.querySelectorAll(".model-pill").forEach((p) => {
				p.classList.toggle("active", p.dataset.level === level);
			});
		});
		container.appendChild(pill);
	}
}

function renderModelListItems(container, models, currentModelId, onSelect) {
	container.innerHTML = "";
	container.style.display = models.length ? "" : "none";
	for (const m of models) {
		const item = document.createElement("button");
		item.type = "button";
		item.className = "model-list-item";
		item.setAttribute("role", "option");
		const value = `${m.provider}/${m.id}`;
		item.dataset.value = value;
		item.appendChild(document.createTextNode(m.name || m.id));
		if (value === currentModelId) {
			item.appendChild(createElement("span", "model-tag", "current"));
		}
		if (value === selectedModel) {
			item.classList.add("selected");
			item.setAttribute("aria-selected", "true");
		}
		item.addEventListener("click", () => onSelect(value));
		container.appendChild(item);
	}
}

function initModelBar(modelsData) {
	if (isClosed) return;
	if (!modelsData || !Array.isArray(modelsData.available) || modelsData.available.length < 2) return;

	const bar = createElement("div", "model-bar");
	const top = createElement("div", "model-bar-top");
	const labelGroup = createElement("div", "model-bar-label-group");
	labelGroup.appendChild(createElement("span", "model-bar-label", "Generate with"));
	top.appendChild(labelGroup);

	const defaultLabel = createElement("label", "model-default-label");
	const defaultCheck = document.createElement("input");
	defaultCheck.type = "checkbox";
	defaultCheck.className = "model-default-check";
	defaultLabel.appendChild(defaultCheck);
	defaultLabel.append(" Default");
	defaultLabel.title = "Save as default for future decks";
	top.appendChild(defaultLabel);
	bar.appendChild(top);

	const byProvider = {};
	for (const m of modelsData.available) {
		(byProvider[m.provider] ??= []).push(m);
	}

	const pills = createElement("div", "model-pills");
	const currentPill = document.createElement("button");
	currentPill.type = "button";
	currentPill.className = "model-pill active";
	currentPill.dataset.provider = "";
	currentPill.textContent = `Current (${modelsData.current ? modelsData.current.split("/").pop() : "current"})`;
	pills.appendChild(currentPill);
	for (const provider of Object.keys(byProvider).sort()) {
		const pill = document.createElement("button");
		pill.type = "button";
		pill.className = "model-pill";
		pill.dataset.provider = provider;
		pill.textContent = provider;
		pills.appendChild(pill);
	}
	bar.appendChild(pills);

	const list = createElement("div", "model-list");
	list.setAttribute("role", "listbox");
	list.setAttribute("aria-label", "Available models");
	list.style.display = "none";
	bar.appendChild(list);

	const selectedLabelEl = createElement("span", "model-selected");
	selectedLabelEl.style.display = "none";
	labelGroup.appendChild(selectedLabelEl);

	const thinkingRow = createElement("div", "thinking-row");
	thinkingRow.style.display = "none";
	thinkingRow.appendChild(createElement("span", "thinking-label", "Thinking"));
	const thinkingPills = createElement("div", "thinking-pills");
	thinkingRow.appendChild(thinkingPills);
	bar.appendChild(thinkingRow);

	selectedThinking = modelsData.currentThinking || "off";
	let activeProvider = "";
	const currentModelId = modelsData.current || "";

	function getSelectedModelInfo() {
		if (!selectedModel) {
			return { reasoning: modelsData.currentModelReasoning, id: currentModelId.split("/")[1] || "" };
		}
		const found = modelsData.available.find((m) => `${m.provider}/${m.id}` === selectedModel);
		return found ? { reasoning: found.reasoning, id: found.id } : null;
	}

	function syncThinkingRow() {
		if (selectedModel) { thinkingRow.style.display = "none"; return; }
		const info = getSelectedModelInfo();
		if (!info || !info.reasoning) { thinkingRow.style.display = "none"; return; }
		thinkingRow.style.display = "";
		renderThinkingPills(thinkingPills, info.id);
	}

	function syncSelectedLabel() {
		if (!selectedModel) { selectedLabelEl.style.display = "none"; return; }
		const model = modelsData.available.find((m) => `${m.provider}/${m.id}` === selectedModel);
		selectedLabelEl.textContent = model ? (model.name || model.id) : selectedModel;
		selectedLabelEl.style.display = "";
	}

	function syncDefaultCheck() {
		const effectiveModel = selectedModel || modelsData.current;
		defaultCheck.checked = modelsData.defaultModel != null && effectiveModel === modelsData.defaultModel;
	}

	function activateProvider(provider) {
		activeProvider = provider;
		pills.querySelectorAll(".model-pill").forEach((p) => {
			p.classList.toggle("active", p.dataset.provider === provider);
		});
		if (!provider) {
			selectedModel = "";
			syncDefaultCheck();
			list.style.display = "none";
			list.innerHTML = "";
			syncSelectedLabel();
			syncThinkingRow();
			return;
		}
		renderModelListItems(list, byProvider[provider] || [], currentModelId, (value) => {
			selectedModel = value;
			syncDefaultCheck();
			list.style.display = "none";
			syncSelectedLabel();
			syncThinkingRow();
		});
	}

	pills.addEventListener("click", (e) => {
		const pill = e.target.closest(".model-pill");
		if (pill) activateProvider(pill.dataset.provider);
	});

	defaultCheck.addEventListener("change", async () => {
		// Use selectedModel, or fall back to current model when on "Current" pill
		const modelToSave = selectedModel || modelsData.current;
		if (defaultCheck.checked && !modelToSave) { defaultCheck.checked = false; return; }
		const model = defaultCheck.checked ? modelToSave : null;
		try {
			await postJson("/save-model-default", { token: [REDACTED], model });
			modelsData.defaultModel = model;
		} catch (err) {
			console.error("Failed to save default model:", err);
			// Revert checkbox to match actual state
			syncDefaultCheck();
		}
	});

	if (modelsData.defaultModel) {
		const parts = modelsData.defaultModel.split("/");
		if (parts.length >= 2 && byProvider[parts[0]]) {
			selectedModel = modelsData.defaultModel;
			activateProvider(parts[0]);
			list.style.display = "none";
			syncSelectedLabel();
		}
	}
	syncDefaultCheck();
	syncThinkingRow();

	const header = document.querySelector(".deck-header");
	if (header) header.after(bar);
	hasModelBar = true;
}

// ─── MERMAID RENDERING ───────────────────────────────────────

let mermaidReady = false;
let mermaidPromise = null;
const mermaidQueue = [];

function loadMermaid() {
	if (mermaidPromise) return;
	mermaidPromise = import("https://cdn.jsdelivr.net/npm/mermaid@11/dist/mermaid.esm.min.mjs")
		.then(({ default: mermaid }) => {
			window.__mermaid = mermaid;
			mermaid.initialize({
				startOnLoad: false,
				theme: "base",
				themeVariables: {
					background: "#1a1a22",
					primaryColor: "#2a3f3d",
					primaryTextColor: "#e0e0e0",
					primaryBorderColor: "#8abeb7",
					lineColor: "#555555",
					secondaryColor: "#1e2a2e",
					tertiaryColor: "#1a1a22",
					noteBkgColor: "#222230",
					noteTextColor: "#b0b0b0",
					fontSize: "13px",
					fontFamily: "'Space Mono', monospace",
				},
			});
			mermaidReady = true;
			for (const render of mermaidQueue.splice(0)) render();
		})
		.catch(() => {});
}

function whenMermaidReady(fn) {
	if (mermaidReady) {
		fn();
		return;
	}
	mermaidQueue.push(fn);
	loadMermaid();
}

let mermaidCounter = 0;

async function renderMermaidBlock(container, content, themeOverrides) {
	const mermaid = window.__mermaid;
	if (!mermaid) return;

	let finalContent = content;
	if (themeOverrides && Object.keys(themeOverrides).length > 0) {
		const vars = Object.entries(themeOverrides)
			.map(([k, v]) => `    ${k}: '${v}'`)
			.join("\n");
		finalContent = `---\nconfig:\n  themeVariables:\n${vars}\n---\n${content}`;
	}

	const id = `mermaid-${++mermaidCounter}`;
	try {
		const { svg } = await mermaid.render(id, finalContent);
		container.innerHTML = svg;
	} catch {
		container.textContent = "Mermaid render error";
		container.style.color = "#f87171";
		container.style.fontSize = "12px";
		container.style.padding = "12px";
	}
	const slide = container.closest(".slide");
	if (slide) equalizeBlockHeights(slide);
}

const PRISM_THEME_URL = "https://cdn.jsdelivr.net/npm/prismjs@1/themes/prism-tomorrow.min.css";
const PRISM_CORE_URL = "https://cdn.jsdelivr.net/npm/prismjs@1/prism.min.js";
const PRISM_AUTOLOADER_URL = "https://cdn.jsdelivr.net/npm/prismjs@1/plugins/autoloader/prism-autoloader.min.js";
let prismPromise = null;

function loadScript(src) {
	return new Promise((resolve, reject) => {
		const script = document.createElement("script");
		script.src = src;
		script.onload = resolve;
		script.onerror = reject;
		document.head.appendChild(script);
	});
}

function loadPrism() {
	if (prismPromise) return prismPromise;
	if (window.Prism?.highlightElement) return Promise.resolve(window.Prism);

	if (!document.querySelector(`link[href="${PRISM_THEME_URL}"]`)) {
		const stylesheet = document.createElement("link");
		stylesheet.rel = "stylesheet";
		stylesheet.href = PRISM_THEME_URL;
		document.head.appendChild(stylesheet);
	}
	prismPromise = loadScript(PRISM_CORE_URL)
		.then(() => loadScript(PRISM_AUTOLOADER_URL))
		.then(() => window.Prism);
	return prismPromise;
}

function renderCodeBlock(container, code, lang) {
	const pre = document.createElement("pre");
	pre.tabIndex = -1;
	const codeEl = document.createElement("code");
	codeEl.className = `language-${lang}`;
	codeEl.textContent = code;
	pre.appendChild(codeEl);
	container.appendChild(pre);

	if (window.Prism?.highlightElement) {
		window.Prism.highlightElement(codeEl);
	} else {
		loadPrism().then((prism) => prism.highlightElement(codeEl)).catch(() => {});
	}
}

// ─── PREVIEW BLOCKS ──────────────────────────────────────────

function renderPreviewBlocks(preview, blocks) {
	preview.classList.add("preview-blocks");
	for (const block of blocks) {
		if (block.type === "html") {
			const wrapper = createElement("div", "preview-block preview-block-html");
			wrapper.innerHTML = block.content;
			preview.appendChild(wrapper);
		} else if (block.type === "mermaid") {
			const wrapper = createElement("div", "preview-block preview-block-mermaid");
			wrapper.tabIndex = -1;
			preview.appendChild(wrapper);
			whenMermaidReady(() => renderMermaidBlock(wrapper, block.content, block.theme));
		} else if (block.type === "code") {
			const wrapper = createElement("div", "preview-block preview-block-code");
			renderCodeBlock(wrapper, block.code, block.lang);
			preview.appendChild(wrapper);
		} else if (block.type === "image") {
			const wrapper = createElement("div", "preview-block preview-block-image");
			const img = document.createElement("img");
			img.src = block.src;
			img.alt = block.alt;
			img.loading = "lazy";
			img.onload = () => { const s = wrapper.closest(".slide"); if (s) equalizeBlockHeights(s); };
			wrapper.appendChild(img);
			if (block.caption) {
				const cap = createElement("div", "preview-block-caption", block.caption);
				wrapper.appendChild(cap);
			}
			preview.appendChild(wrapper);
		}
	}
}

function applyPreviewHtml(preview, previewHtml) {
	if (typeof previewHtml !== "string") return;
	const trimmed = previewHtml.trim();
	if (!trimmed) return;

	const temp = document.createElement("div");
	temp.innerHTML = trimmed;
	const first = temp.firstElementChild;

	if (first && first.classList.contains("preview")) {
		const dataset = first.dataset || {};
		if (dataset.theme) {
			preview.dataset.theme = dataset.theme;
		}
		if (dataset.fonts) {
			preview.dataset.fonts = dataset.fonts;
		}
		// Copy inline styles from source preview div
		if (first.style.cssText) {
			preview.style.cssText = first.style.cssText;
		}
		preview.innerHTML = first.innerHTML;
		return;
	}

	preview.innerHTML = previewHtml;
}

// ─── OPTION CARDS ────────────────────────────────────────────

function optionCountClass(count, columns) {
	if (columns === 1) return "cols-1";
	if (columns && count >= columns && count % columns !== 1) {
		return `cols-${columns}`;
	}
	if (count <= 1) return "cols-1";
	if (count === 2 || count === 4) return "cols-2";
	return "cols-3";
}

function optionHint(count) {
	const max = Math.min(9, Math.max(1, count));
	const parts = [];
	for (let i = 1; i <= max; i += 1) {
		parts.push(`<kbd>${i}</kbd>`);
	}
	return `Choose one - press ${parts.join(" ")} or click`;
}

function createOptionCard(option, slideId, generatedBy) {
	const card = createElement("div", "option");
	card.setAttribute("role", "radio");
	card.setAttribute("aria-checked", "false");
	card.tabIndex = 0;
	if (generatedBy !== false) {
		card.classList.add("option-generated");
	}
	card.dataset.value = option.label;
	card.addEventListener("click", () => selectOption(card));

	const check = createElement("div", "option-check");
	check.innerHTML = "&#10003;";
	card.appendChild(check);

	const header = createElement("div", "option-header");	
	const radio = createElement("span", "option-radio");
	header.appendChild(radio);

	const label = createElement("span", "option-label", option.label);
	header.appendChild(label);

	if (generatedBy !== false) {
		const modelShort = generatedBy ? generatedBy.split("/").pop() : null;
		const badgeText = modelShort ? `Generated by ${modelShort}` : "Generated";
		header.appendChild(createElement("span", "badge-generated", badgeText));
	} else if (option.recommended) {
		header.appendChild(createElement("span", "rec-badge", "Recommended"));
	}

	header.appendChild(createElement("span", "option-num"));
	card.appendChild(header);

	const preview = createElement("div", "preview");
	if (Array.isArray(option.previewBlocks) && option.previewBlocks.length > 0) {
		renderPreviewBlocks(preview, option.previewBlocks);
	} else {
		applyPreviewHtml(preview, option.previewHtml);
	}
	card.appendChild(preview);
	preview.querySelectorAll("a, button, input, select, textarea, pre, [contenteditable]").forEach((el) => {
		el.tabIndex = -1;
	});

	// Footer contains aside (optional) + notes input
	const footer = createElement("div", "option-footer");

	if (option.aside) {
		const aside = createElement("div", "option-aside");
		// Handle both actual newlines and literal \n sequences
		aside.innerHTML = escapeHtml(option.aside).replace(/\\n/g, "<br>").replace(/\n/g, "<br>");
		footer.appendChild(aside);
	}

	// Notes input for user instructions
	const notesContainer = createElement("div", "option-notes");
	const notesLabel = createElement("label", "option-notes-label", "Your notes (optional)");
	const notesInput = createElement("textarea", "option-notes-input");
	notesInput.placeholder = "Add notes...";
	notesInput.rows = 1;
	notesInput.dataset.slideId = slideId;
	notesInput.dataset.optionLabel = option.label;

	// Restore saved notes if this option was previously selected with notes
	if (optionNotes[slideId]?.label === option.label && optionNotes[slideId]?.notes) {
		notesInput.value = optionNotes[slideId].notes;
	}

	notesInput.addEventListener("input", (e) => {
		const value = e.target.value.trim();
		if (value) {
			optionNotes[slideId] = { label: option.label, notes: value };
		} else if (optionNotes[slideId]?.label === option.label) {
			delete optionNotes[slideId];
		}
		saveSelectionsToStorage();
		markDirty();
	});

	// Prevent click from bubbling to card (which would select it)
	notesInput.addEventListener("click", (e) => e.stopPropagation());

	notesContainer.appendChild(notesLabel);
	notesContainer.appendChild(notesInput);
	footer.appendChild(notesContainer);
	card.appendChild(footer);

	if (option.description) {
		card.setAttribute("title", option.description);
	}

	if (selections[slideId] && selections[slideId] === option.label) {
		card.classList.add("selected");
	}

	return card;
}

function createGenerateBar(slideId) {
	const bar = createElement("div", "gen-bar");

	const row = createElement("div", "gen-row");

	// Generate button with separate count selector
	const genGroup = createElement("div", "gen-group");
	const button = createElement("button", "btn-gen-more");
	button.type = "button";
	button.appendChild(createElement("span", "btn-gen-plus", "+"));
	button.appendChild(document.createTextNode("Generate"));

	const countSelect = document.createElement("select");
	countSelect.className = "gen-count";
	countSelect.setAttribute("aria-label", "Number of options to generate");
	[1, 2, 3].forEach((n) => {
		const opt = document.createElement("option");
		opt.value = n;
		opt.textContent = n;
		countSelect.appendChild(opt);
	});

	const countLabel = createElement("span", "gen-count-label", "option");
	countSelect.addEventListener("change", () => {
		const count = parseInt(countSelect.value, 10);
		countLabel.textContent = count === 1 ? "option" : "options";
	});

	genGroup.appendChild(button);
	genGroup.appendChild(countSelect);
	genGroup.appendChild(countLabel);

	const regenButton = createElement("button", "btn-regen");
	regenButton.type = "button";
	regenButton.innerHTML = "↻ Regenerate all";
	regenButton.title = "Replace all options with fresh alternatives";
	regenButton.addEventListener("click", () => regenerateSlide(regenButton, slideId));

	const input = document.createElement("input");
	input.type = "text";
	input.className = "gen-prompt";
	input.placeholder = "Optional instructions...";
	input.setAttribute("aria-label", "Instructions for generated option");
	input.addEventListener("keydown", (e) => {
		if (e.key === "Enter") {
			e.preventDefault();
			button.click();
		}
		e.stopPropagation();
	});

	button.addEventListener("click", () => generateMore(button, slideId, input, countSelect));
	row.appendChild(genGroup);
	row.appendChild(regenButton);
	row.appendChild(input);
	bar.appendChild(row);

	const hint = createElement("span", "gen-hint", "AI generates a distinct additional option");
	hint.setAttribute("role", "status");
	bar.appendChild(hint);
	return bar;
}

// ─── SLIDE RENDERING ─────────────────────────────────────────

function renderSlides() {
	slidesWrap.innerHTML = "";

	slides.forEach((slide, index) => {
		const section = createElement("div", "slide");
		section.dataset.slide = String(index);
		section.dataset.id = slide.id;
		if (index === 0) section.classList.add("active");

		section.appendChild(createElement("span", "slide-step", `${index + 1} / ${slides.length}`));
		const heading = createElement("h2", "", slide.title);
		heading.tabIndex = -1;
		section.appendChild(heading);
		if (slide.context) {
			section.appendChild(createElement("p", "slide-context", slide.context));
		}

		const pick = createElement("p", "slide-pick");
		pick.innerHTML = optionHint(slide.options.length);
		section.appendChild(pick);

		const options = createElement("div", `options ${optionCountClass(slide.options.length, slide.columns)}`);
		options.setAttribute("role", "radiogroup");
		options.setAttribute("aria-label", slide.title);
		slide.options.forEach((option) => {
			const card = createOptionCard(option, slide.id, false);
			options.appendChild(card);
		});
		section.appendChild(options);
		section.appendChild(createGenerateBar(slide.id));
		slidesWrap.appendChild(section);
		equalizeBlockHeights(section);
	});

	slidesWrap.appendChild(createSummarySlide(slides.length));
}

function createSummarySlide(index) {
	const section = createElement("div", "slide");
	section.dataset.slide = String(index);
	section.dataset.id = "summary";
	section.appendChild(createElement("span", "slide-step", "Done"));
	const summaryHeading = createElement("h2", "", "Your Selections");
	summaryHeading.tabIndex = -1;
	section.appendChild(summaryHeading);

	const summaryDesc = createElement("p", "slide-context");
	summaryDesc.id = "summary-desc";
	summaryDesc.setAttribute("aria-live", "polite");
	summaryDesc.textContent = "Select one option per slide.";
	section.appendChild(summaryDesc);

	const summaryGrid = createElement("div", "summary-grid");
	summaryGrid.id = "summary-grid";
	section.appendChild(summaryGrid);

	// Final instructions textarea
	const finalNotesContainer = createElement("div", "final-notes");
	const finalNotesLabel = createElement("label", "final-notes-label", "Additional instructions (optional)");
	finalNotesLabel.setAttribute("for", "final-notes-input");
	const finalNotesInput = createElement("textarea", "final-notes-input");
	finalNotesInput.id = "final-notes-input";
	finalNotesInput.placeholder = "Add any final notes or instructions for implementation...";
	finalNotesInput.rows = 2;
	finalNotesInput.addEventListener("input", (e) => {
		finalNotes = e.target.value.trim();
		saveSelectionsToStorage();
		markDirty();
	});
	finalNotesContainer.appendChild(finalNotesLabel);
	finalNotesContainer.appendChild(finalNotesInput);
	section.appendChild(finalNotesContainer);

	const submitButton = createElement("button", "btn-generate", "Submit Selections");
	submitButton.type = "button";
	submitButton.id = "btn-generate";
	submitButton.disabled = true;
	submitButton.addEventListener("click", () => {
		submitDeck().catch(() => {});
	});
	section.appendChild(submitButton);

	return section;
}

// ─── SUMMARY ─────────────────────────────────────────────────

function findOption(slideId, label) {
	const slide = slides.find((entry) => entry.id === slideId);
	if (!slide) return null;
	return slide.options.find((entry) => entry.label === label) || null;
}

function createSummaryCard(slide) {
	const card = createElement("div", "summary-card");
	card.appendChild(createElement("div", "summary-label", slide.title));

	const selectedLabel = selections[slide.id];
	card.appendChild(createElement("div", "summary-value", selectedLabel || "-"));

	if (selectedLabel) {
		const selectedOption = findOption(slide.id, selectedLabel);
		if (selectedOption) {
			const previewShell = createElement("div", "summary-preview");

			if (Array.isArray(selectedOption.previewBlocks) && selectedOption.previewBlocks.length > 0) {
				const first = selectedOption.previewBlocks[0];
				if (first.type === "code") {
					const codeSnippet = createElement("div", "summary-code-snippet");
					const pre = document.createElement("pre");
					const codeEl = document.createElement("code");
					codeEl.className = `language-${first.lang}`;
					const lines = first.code.split("\n").slice(0, 3).join("\n");
					codeEl.textContent = lines;
					pre.appendChild(codeEl);
					codeSnippet.appendChild(pre);
					previewShell.appendChild(codeSnippet);
					if (window.Prism?.highlightElement) {
						window.Prism.highlightElement(codeEl);
					} else {
						loadPrism().then((prism) => prism.highlightElement(codeEl)).catch(() => {});
					}
				} else if (first.type === "image") {
					const img = document.createElement("img");
					img.src = first.src;
					img.alt = first.alt;
					img.style.width = "100%";
					img.style.height = "80px";
					img.style.objectFit = "cover";
					img.style.display = "block";
					img.style.borderRadius = "6px";
					previewShell.appendChild(img);
				} else if (first.type === "mermaid") {
					const mermaidWrap = createElement("div", "summary-mermaid");
					mermaidWrap.style.height = "80px";
					mermaidWrap.style.overflow = "hidden";
					previewShell.appendChild(mermaidWrap);
					whenMermaidReady(() => renderMermaidBlock(mermaidWrap, first.content, first.theme));
				} else if (first.type === "html") {
					const preview = createElement("div", "preview");
					preview.innerHTML = first.content;
					previewShell.appendChild(preview);
				}
			} else {
				const preview = createElement("div", "preview");
				applyPreviewHtml(preview, selectedOption.previewHtml);
				previewShell.appendChild(preview);
			}

			card.appendChild(previewShell);

			if (selectedOption.aside) {
				const aside = createElement("div", "summary-aside");
				const text = selectedOption.aside.length > 120
					? selectedOption.aside.slice(0, 120).trimEnd() + "..."
					: selectedOption.aside;
				aside.innerHTML = escapeHtml(text).replace(/\\n/g, "<br>").replace(/\n/g, "<br>");
				card.appendChild(aside);
			}
		}

		// Show user notes if present
		const noteData = optionNotes[slide.id];
		if (noteData && noteData.label === selectedLabel && noteData.notes) {
			const notesDisplay = createElement("div", "summary-notes");
			notesDisplay.innerHTML = `<span class="summary-notes-label">Your notes:</span> ${escapeHtml(noteData.notes)}`;
			card.appendChild(notesDisplay);
		}
	}

	return card;
}

function updateSummary() {
	const summaryGrid = document.getElementById("summary-grid");
	const summaryDesc = document.getElementById("summary-desc");
	const submitButton = document.getElementById("btn-generate");
	if (!summaryGrid || !summaryDesc || !submitButton) return;

	summaryGrid.innerHTML = "";
	slides.forEach((slide) => {
		summaryGrid.appendChild(createSummaryCard(slide));
	});

	const missing = slides.filter((slide) => !selections[slide.id]).map((slide) => slide.title);
	const allDone = missing.length === 0;

	summaryDesc.textContent = allDone
		? "All decisions made. Ready to submit."
		: `Still need: ${missing.join(", ")}.`;

	submitButton.disabled = !allDone || isClosed || isSubmitting;
}

// ─── STATE & CONFIGURATION ───────────────────────────────────

const deckData = window.__DECK_DATA__ || {};
const config =
	deckData && typeof deckData === "object" && deckData.config && typeof deckData.config === "object"
		? deckData.config
		: { slides: [] };

const sessionToken = typeof deckData.sessionToken === "string" ? deckData.sessionToken : "";

const slides = Array.isArray(config.slides)
	? config.slides.map((slide) => ({
			...slide,
			options: Array.isArray(slide.options) ? [...slide.options] : [],
		}))
	: [];

const totalSlides = slides.length + 1;
let current = 0;
let events = null;
let heartbeatTimer = null;
let isClosed = false;
let isSubmitting = false;
let isDirty = false;
let lastSavedLabel = "";
let isRestoringSelections = false;

const selections = {};
const optionNotes = {};
let finalNotes = "";
const pendingGenerate = new Map();
let selectedModel = "";
let selectedThinking = "off";
let hasModelBar = false;

// DOM references
const progressFill = document.getElementById("progress-fill");
const slidesWrap = document.getElementById("slides-wrap");
const btnBack = document.getElementById("btn-back");
const btnNext = document.getElementById("btn-next");
const btnSave = document.getElementById("btn-save");
const saveStatus = document.getElementById("save-status");

// ─── UTILITIES ───────────────────────────────────────────────

function createElement(tag, className, text) {
	const el = document.createElement(tag);
	if (className) el.className = className;
	if (text !== undefined) el.textContent = text;
	return el;
}

function escapeHtml(str) {
	return str.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

function equalizeBlockHeights(container) {
	const types = ["mermaid", "code", "html", "image"];
	for (const type of types) {
		const blocks = container.querySelectorAll(`.preview-block-${type}`);
		if (blocks.length < 2) continue;
		blocks.forEach((b) => { b.style.height = ""; });
		let maxH = 0;
		blocks.forEach((b) => { maxH = Math.max(maxH, b.offsetHeight); });
		if (maxH > 0) blocks.forEach((b) => { b.style.height = maxH + "px"; });
	}
}

function setMetaLabel() {
	const deckTitle = document.getElementById("deck-title");
	if (!deckTitle) return;
	const title = typeof config.title === "string" && config.title ? config.title : "Design Decisions";
	const cwd = typeof deckData.cwd === "string" ? deckData.cwd : "";
	const gitBranch = typeof deckData.gitBranch === "string" ? deckData.gitBranch : "";
	if (cwd) {
		deckTitle.textContent = `${title} - ${cwd}${gitBranch ? ` (${gitBranch})` : ""}`;
		return;
	}
	deckTitle.textContent = title;
}

function formatSavedTimestamp(value) {
	try {
		return new Date(value).toLocaleTimeString([], { hour: "numeric", minute: "2-digit" });
	} catch {
		return "";
	}
}

function updateSaveStatus() {
	if (saveStatus) {
		if (isDirty) {
			saveStatus.textContent = "Unsaved changes";
			saveStatus.classList.add("dirty");
			saveStatus.classList.remove("saved");
		} else if (lastSavedLabel) {
			saveStatus.textContent = `Saved ${lastSavedLabel}`;
			saveStatus.classList.add("saved");
			saveStatus.classList.remove("dirty");
		} else {
			saveStatus.textContent = "No unsaved changes";
			saveStatus.classList.remove("dirty", "saved");
		}
	}
	if (btnSave) {
		btnSave.disabled = isClosed;
		btnSave.classList.toggle("dirty", isDirty);
	}
}

function markDirty() {
	if (isClosed) return;
	isDirty = true;
	updateSaveStatus();
}

function markSaved(savedAt) {
	isDirty = false;
	lastSavedLabel = formatSavedTimestamp(savedAt || new Date().toISOString());
	updateSaveStatus();
}

// ─── THEME SYSTEM ────────────────────────────────────────────

const themeConfig = deckData && typeof deckData === "object" && deckData.theme && typeof deckData.theme === "object" ? deckData.theme : {};
const themeMode = typeof themeConfig.mode === "string" ? themeConfig.mode : "dark";
const themeToggleHotkey = typeof themeConfig.toggleHotkey === "string" ? themeConfig.toggleHotkey : "";
const THEME_OVERRIDE_KEY = "pi-deck-theme-override";

function getSystemTheme() {
	return window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
}

function getStoredThemeOverride() {
	try {
		const value = localStorage.getItem(THEME_OVERRIDE_KEY);
		return value === "light" || value === "dark" ? value : null;
	} catch { return null; }
}

function setStoredThemeOverride(value) {
	try {
		if (!value) { localStorage.removeItem(THEME_OVERRIDE_KEY); return; }
		localStorage.setItem(THEME_OVERRIDE_KEY, value);
	} catch {}
}

function getEffectiveTheme() {
	const override = getStoredThemeOverride();
	if (override) return override;
	if (themeMode === "auto") return getSystemTheme();
	return themeMode;
}

function applyTheme(mode) {
	document.documentElement.dataset.theme = mode;
	document.documentElement.style.colorScheme = mode;
	const meta = document.querySelector('meta[name="theme-color"]');
	if (meta) meta.content = mode === "light" ? "#f8f8f8" : "#18181e";
}

function toggleTheme() {
	const currentTheme = getEffectiveTheme();
	const next = currentTheme === "dark" ? "light" : "dark";
	if (themeMode === "auto") {
		setStoredThemeOverride(next === getSystemTheme() ? null : next);
	} else {
		setStoredThemeOverride(next);
	}
	applyTheme(next);
}

function parseHotkey(value) {
	if (!value) return null;
	const parts = value.toLowerCase().split("+").map((p) => p.trim()).filter(Boolean);
	if (parts.length === 0) return null;
	const key = parts[parts.length - 1];
	const mods = parts.slice(0, -1);
	const hotkey = { key, mod: false, shift: false, alt: false };
	mods.forEach((m) => {
		if (m === "mod" || m === "cmd" || m === "meta" || m === "ctrl" || m === "control") hotkey.mod = true;
		else if (m === "shift") hotkey.shift = true;
		else if (m === "alt" || m === "option") hotkey.alt = true;
	});
	return key ? hotkey : null;
}

function matchesHotkey(event, hotkey) {
	if (event.key.toLowerCase() !== hotkey.key) return false;
	const isMac = navigator.platform.toUpperCase().indexOf("MAC") >= 0;
	const modPressed = isMac ? event.metaKey : event.ctrlKey;
	if (hotkey.mod !== modPressed) return false;
	if (hotkey.shift !== event.shiftKey) return false;
	if (hotkey.alt !== event.altKey) return false;
	if (!hotkey.mod && (event.metaKey || event.ctrlKey)) return false;
	if (!hotkey.shift && event.shiftKey) return false;
	if (!hotkey.alt && event.altKey) return false;
	return true;
}

function initTheme() {
	applyTheme(getEffectiveTheme());

	if (themeMode === "auto") {
		const media = window.matchMedia("(prefers-color-scheme: dark)");
		media.addEventListener("change", () => {
			if (!getStoredThemeOverride()) applyTheme(getSystemTheme());
		});
	}

	const hotkey = parseHotkey(themeToggleHotkey);
	if (hotkey) {
		const shortcut = document.getElementById("theme-shortcut");
		if (shortcut) {
			const isMac = navigator.platform.toUpperCase().indexOf("MAC") >= 0;
			const parts = [];
			if (hotkey.mod) parts.push(isMac ? "⌘" : "Ctrl");
			if (hotkey.shift) parts.push("Shift");
			if (hotkey.alt) parts.push(isMac ? "Option" : "Alt");
			parts.push(hotkey.key.length === 1 ? hotkey.key.toUpperCase() : hotkey.key);
			shortcut.innerHTML = parts.map((p) => `<kbd>${p}</kbd>`).join("") + " Theme";
			shortcut.classList.remove("hidden");
		}
		document.addEventListener("keydown", (event) => {
			if (matchesHotkey(event, hotkey)) { event.preventDefault(); toggleTheme(); }
		});
	}
}

// ─── LAYOUT TOGGLE ───────────────────────────────────────────

const LAYOUT_KEY = "pi-deck-layout";

function getStoredLayout() {
	try {
		const value = localStorage.getItem(LAYOUT_KEY);
		return value === "1" || value === "2" || value === "3" || value === "4" ? value : null;
	} catch { return null; }
}

function setStoredLayout(value) {
	try {
		if (!value) {
			localStorage.removeItem(LAYOUT_KEY);
		} else {
			localStorage.setItem(LAYOUT_KEY, value);
		}
	} catch {}
}

function applyLayout(cols) {
	const deck = document.querySelector(".deck");
	if (!deck) return;
	if (cols) {
		deck.dataset.layout = cols;
	} else {
		delete deck.dataset.layout;
	}
}

function updateLayoutButtons(activeCols) {
	const toggle = document.getElementById("layout-toggle");
	if (!toggle) return;
	toggle.querySelectorAll(".layout-btn").forEach((btn) => {
		const isActive = btn.dataset.cols === activeCols;
		btn.classList.toggle("active", isActive);
		btn.setAttribute("aria-pressed", isActive ? "true" : "false");
		// Update title to show "Auto" hint when clicking would reset
		const cols = btn.dataset.cols;
		btn.title = isActive ? `${cols} column${cols === "1" ? "" : "s"} (click for auto)` : `${cols} column${cols === "1" ? "" : "s"}`;
	});
}

function initLayoutToggle() {
	const stored = getStoredLayout();
	if (stored) {
		applyLayout(stored);
		updateLayoutButtons(stored);
	}

	const toggle = document.getElementById("layout-toggle");
	if (!toggle) return;

	toggle.addEventListener("click", (event) => {
		const btn = event.target.closest(".layout-btn");
		if (!btn) return;
		const cols = btn.dataset.cols;
		const stored = getStoredLayout();
		if (cols === stored) {
			// Clicking active button toggles back to auto
			setStoredLayout(null);
			applyLayout(null);
			updateLayoutButtons(null);
		} else {
			setStoredLayout(cols);
			applyLayout(cols);
			updateLayoutButtons(cols);
		}
	});
}

// ─── SELECTION PERSISTENCE ────────────────────────────────────

const SELECTIONS_KEY = `pi-deck-${typeof deckData.sessionId === "string" ? deckData.sessionId : "unknown"}`;

function saveSelectionsToStorage() {
	try { 
		const data = { selections, optionNotes };
		if (finalNotes) data.finalNotes = finalNotes;
		localStorage.setItem(SELECTIONS_KEY, JSON.stringify(data)); 
	} catch {}
}

function loadSelectionsFromStorage() {
	try {
		const saved = localStorage.getItem(SELECTIONS_KEY);
		if (!saved) return null;
		const parsed = JSON.parse(saved);
		// Handle both old format (just selections) and new format ({ selections, optionNotes })
		if (parsed && typeof parsed === "object" && !parsed.selections) {
			return { selections: parsed, optionNotes: {} };
		}
		return parsed;
	} catch { return null; }
}

function clearSelectionsStorage() {
	try { localStorage.removeItem(SELECTIONS_KEY); } catch {}
}

// ─── NETWORK ─────────────────────────────────────────────────

async function postJson(path, payload) {
	const response = await fetch(path, {
		method: "POST",
		headers: { "Content-Type": "application/json" },
		body: JSON.stringify(payload),
	});

	if (!response.ok) {
		let message = `Request failed (${response.status})`;
		try {
			const data = await response.json();
			if (data && typeof data.error === "string") {
				message = data.error;
			}
		} catch {}
		throw new Error(message);
	}

	try {
		return await response.json();
	} catch {
		return { ok: true };
	}
}

// ─── SAVE/SNAPSHOT ───────────────────────────────────────────

let saveToastTimer = null;

function showSaveToast(message, isError) {
	const toast = document.getElementById("save-toast");
	if (!toast) return;
	if (saveToastTimer) { clearTimeout(saveToastTimer); saveToastTimer = null; }
	toast.textContent = message;
	toast.className = `save-toast ${isError ? "error" : "success"}`;
	toast.style.animation = "none";
	toast.offsetHeight;
	toast.style.animation = "";
	saveToastTimer = setTimeout(() => { toast.classList.add("hidden"); saveToastTimer = null; }, 3000);
}

function buildSelectedNotes() {
	const notes = {};
	for (const [slideId, noteData] of Object.entries(optionNotes)) {
		if (noteData && selections[slideId] === noteData.label && noteData.notes) {
			notes[slideId] = noteData.notes;
		}
	}
	return notes;
}

async function saveDeck() {
	if (isClosed) return;
	try {
		const payload = { token: [REDACTED], selections, notes: buildSelectedNotes() };
		if (finalNotes) payload.finalNotes = finalNotes;
		const result = await postJson("/save", payload);
		if (result.ok) {
			markSaved(new Date().toISOString());
			showSaveToast(`Saved to ${result.relativePath}`);
		}
		else showSaveToast(result.error || "Save failed", true);
	} catch {
		showSaveToast("Save failed", true);
	}
}

// ─── SESSION LIFECYCLE ───────────────────────────────────────

function closeEvents() {
	if (events) {
		events.close();
		events = null;
	}
}

function stopHeartbeat() {
	if (heartbeatTimer) {
		clearInterval(heartbeatTimer);
		heartbeatTimer = null;
	}
}

function disableDeckInteractions() {
	if (btnBack) btnBack.disabled = true;
	if (btnNext) btnNext.disabled = true;
	if (btnSave) btnSave.disabled = true;
	document.querySelectorAll(".btn-gen-more, .btn-regen").forEach((button) => {
		button.disabled = true;
	});
	document.querySelectorAll(".gen-prompt, .gen-count").forEach((input) => {
		input.disabled = true;
	});
	document.querySelectorAll(".model-pill, .model-list-item, .model-default-check").forEach((el) => {
		el.disabled = true;
	});
}

async function submitDeck() {
	if (isClosed || isSubmitting) return;
	const allDone = slides.every((slide) => !!selections[slide.id]);
	if (!allDone) {
		updateSummary();
		return;
	}

	isSubmitting = true;
	const submitButton = document.getElementById("btn-generate");
	if (submitButton) {
		submitButton.textContent = "Submitting...";
		submitButton.disabled = true;
	}

	try {
		const notes = buildSelectedNotes();
		const payload = { token: [REDACTED], selections, notes };
		if (finalNotes) payload.finalNotes = finalNotes;
		await postJson("/submit", payload);
		clearSelectionsStorage();
		isClosed = true;
		if (submitButton) {
			submitButton.textContent = "Submitted";
			submitButton.style.background = "var(--dk-status-success)";
		}
		stopHeartbeat();
		closeEvents();
		disableDeckInteractions();
		clearPendingGenerates();
		showCloseOverlay("submitted");
	} catch {
		isSubmitting = false;
		if (submitButton) {
			submitButton.textContent = "Submit Selections";
		}
		updateSummary();
	}
}

// ─── CONFIRM BAR & CLOSE OVERLAY ─────────────────────────────

let confirmBarTimeout = null;

function hasAnySelections() {
	return Object.keys(selections).length > 0;
}

function showConfirmBar() {
	const bar = document.getElementById("confirm-bar");
	if (!bar) return;
	bar.classList.add("visible");

	clearConfirmBarTimeout();
	confirmBarTimeout = setTimeout(() => hideConfirmBar(), 5000);
}

function hideConfirmBar() {
	const bar = document.getElementById("confirm-bar");
	if (bar) bar.classList.remove("visible");
	clearConfirmBarTimeout();
}

function clearConfirmBarTimeout() {
	if (confirmBarTimeout) {
		clearTimeout(confirmBarTimeout);
		confirmBarTimeout = null;
	}
}

function handleEscape() {
	if (isClosed) return;

	const bar = document.getElementById("confirm-bar");
	if (bar && bar.classList.contains("visible")) {
		cancelDeck("user");
		return;
	}

	if (hasAnySelections()) {
		showConfirmBar();
		return;
	}

	cancelDeck("user");
}

function showCloseOverlay(reason) {
	const overlay = document.getElementById("close-overlay");
	const content = document.getElementById("close-overlay-content");
	if (!overlay || !content) return;

	const messages = {
		submitted: { text: "Selections sent to agent. You can close this tab.", cls: "close-reason-success" },
		user: { text: "Deck cancelled. You can close this tab.", cls: "close-reason-warn" },
		stale: { text: "Session ended — lost connection.", cls: "close-reason-error" },
		aborted: { text: "Session was ended by the agent.", cls: "close-reason-error" },
		closed: { text: "Session was closed.", cls: "close-reason-error" },
	};

	const msg = messages[reason] || messages.closed;
	content.textContent = msg.text;
	overlay.className = `deck-close-overlay visible ${msg.cls}`;
	if (reason === "submitted" || reason === "user") {
		setTimeout(() => { window.close(); }, 800);
	}
}

function cancelDeck(reason) {
	if (isClosed) return;
	isClosed = true;
	hideConfirmBar();
	stopHeartbeat();
	closeEvents();
	disableDeckInteractions();
	clearPendingGenerates();
	showCloseOverlay(reason);
	postJson("/cancel", { token: [REDACTED], reason, selections }).catch(() => {});
}

function sendCancelBeacon() {
	if (isClosed || !sessionToken) return;
	const payload = JSON.stringify({ token: [REDACTED], reason: "user", selections });
	if (navigator.sendBeacon) {
		navigator.sendBeacon("/cancel", new Blob([payload], { type: "application/json" }));
		return;
	}
	fetch("/cancel", {
		method: "POST",
		headers: { "Content-Type": "application/json" },
		body: payload,
		keepalive: true,
	}).catch(() => {});
}

function startHeartbeat() {
	if (!sessionToken) return;

	const ping = () => {
		if (isClosed) return;
		postJson("/heartbeat", { token: [REDACTED] }).catch(() => {});
	};

	ping();
	heartbeatTimer = setInterval(ping, 5000);
}

// ─── GENERATE MORE ───────────────────────────────────────────

function clearPendingGenerates() {
	for (const [slideId, pending] of pendingGenerate.entries()) {
		if (pending.isRegen) {
			restoreRegenButton(slideId);
		} else {
			restoreGenerateButton(slideId);
		}
	}
}

function restoreGenerateButton(slideId) {
	const pending = pendingGenerate.get(slideId);
	if (!pending || pending.isRegen) return;

	// Clear timeout if any
	if (pending.timeoutId) clearTimeout(pending.timeoutId);

	// Remove all skeletons from DOM (query directly, don't rely on array)
	const slideElement = document.querySelector(`.slide[data-id="${CSS.escape(slideId)}"]`);
	if (slideElement) {
		slideElement.querySelectorAll(".option-skeleton").forEach((skel) => skel.remove());
	}

	pending.button.classList.remove("loading");
	const plus = pending.button.querySelector(".btn-gen-plus");
	if (plus) plus.textContent = "+";
	pending.button.lastChild.textContent = "Generate";

	if (pending.input && !isClosed) pending.input.disabled = false;
	if (pending.countSelect && !isClosed) pending.countSelect.disabled = false;

	pendingGenerate.delete(slideId);
}

function reapplySelectionAfterInsert(slideElement, slideId) {
	const selected = selections[slideId];
	if (!selected) return;
	const selectedEl = Array.from(slideElement.querySelectorAll(".option")).find(
		(el) => el.dataset.value === selected
	);
	if (selectedEl) {
		selectedEl.classList.add("selected");
		selectedEl.setAttribute("aria-checked", "true");
	}
}

function insertGeneratedOption(slideId, option, model) {
	const slide = slides.find((entry) => entry.id === slideId);
	if (!slide) return;
	slide.options.push(option);

	const slideElement = document.querySelector(`.slide[data-id="${CSS.escape(slideId)}"]`);
	if (!slideElement) return;

	const optionsGrid = slideElement.querySelector(".options");
	if (!optionsGrid) return;

	optionsGrid.className = `options ${optionCountClass(slide.options.length, slide.columns)}`;

	const optionCard = createOptionCard(option, slideId, model);
	optionsGrid.appendChild(optionCard);
	reapplySelectionAfterInsert(slideElement, slideId);
	equalizeBlockHeights(slideElement);

	const pick = slideElement.querySelector(".slide-pick");
	if (pick) pick.innerHTML = optionHint(slide.options.length);

	if (current === totalSlides - 1) {
		updateSummary();
	}
	markDirty();
}

function replaceSlideOptions(slideId, newOptions) {
	const slide = slides.find((entry) => entry.id === slideId);
	if (!slide) return;

	slide.options = newOptions;

	delete selections[slideId];
	delete optionNotes[slideId];
	saveSelectionsToStorage();

	const slideElement = document.querySelector(`.slide[data-id="${CSS.escape(slideId)}"]`);
	if (!slideElement) return;

	const optionsGrid = slideElement.querySelector(".options");
	if (!optionsGrid) return;

	// Remove regeneration overlay and state
	const overlay = optionsGrid.querySelector(".regen-overlay");
	if (overlay) overlay.remove();
	optionsGrid.classList.remove("regenerating");
	optionsGrid.style.position = "";

	optionsGrid.innerHTML = "";
	optionsGrid.className = `options ${optionCountClass(newOptions.length, slide.columns)}`;

	newOptions.forEach((option) => {
		const card = createOptionCard(option, slideId, false);
		card.classList.add("option-regenerated");
		optionsGrid.appendChild(card);
	});

	// Remove animation class after animation completes
	setTimeout(() => {
		optionsGrid.querySelectorAll(".option-regenerated").forEach((el) => {
			el.classList.remove("option-regenerated");
		});
	}, 500);

	equalizeBlockHeights(slideElement);

	const pick = slideElement.querySelector(".slide-pick");
	if (pick) pick.innerHTML = optionHint(newOptions.length);

	if (current === totalSlides - 1) {
		updateSummary();
	}
	markDirty();
}

function connectEvents() {
	if (!sessionToken) return;
	events = new EventSource(`/events?session=${encodeURIComponent(sessionToken)}`);

	events.addEventListener("new-option", (event) => {
		let payload;
		try {
			payload = JSON.parse(event.data);
		} catch {
			return;
		}
		if (!payload || typeof payload.slideId !== "string" || !payload.option) {
			return;
		}
		const pending = pendingGenerate.get(payload.slideId);
		const model = pending?.model || null;

		// Remove one skeleton
		if (pending?.skeletons?.length > 0) {
			const skel = pending.skeletons.shift();
			if (skel.parentElement) skel.remove();
		}

		insertGeneratedOption(payload.slideId, payload.option, model);

		// Track received count and restore button when all received
		if (pending) {
			pending.receivedCount = (pending.receivedCount || 0) + 1;
			if (pending.receivedCount >= (pending.expectedCount || 1)) {
				restoreGenerateButton(payload.slideId);
			} else {
				// Reset timeout for next option
				if (pending.timeoutId) clearTimeout(pending.timeoutId);
				pending.timeoutId = setTimeout(() => {
					const entry = pendingGenerate.get(payload.slideId);
					if (!entry || entry.isRegen) return;
					const received = entry.receivedCount || 0;
					const expected = entry.expectedCount || 1;
					restoreGenerateButton(payload.slideId);
					if (received < expected) {
						showSaveToast(`Generated ${received} of ${expected} options`, true);
					}
				}, 30000);
			}
		}
	});

	events.addEventListener("generate-failed", (event) => {
		let payload;
		try {
			payload = JSON.parse(event.data);
		} catch {
			return;
		}
		if (payload && typeof payload.slideId === "string") {
			restoreGenerateButton(payload.slideId);
			if (payload.reason === "timeout") {
				showSaveToast("Generation timed out — try again", true);
			} else {
				showSaveToast("Generation failed", true);
			}
		}
	});

	events.addEventListener("replace-options", (event) => {
		let payload;
		try {
			payload = JSON.parse(event.data);
		} catch {
			return;
		}
		if (!payload || typeof payload.slideId !== "string" || !Array.isArray(payload.options)) {
			return;
		}
		restoreRegenButton(payload.slideId);
		replaceSlideOptions(payload.slideId, payload.options);
	});

	events.addEventListener("regenerate-failed", (event) => {
		let payload;
		try {
			payload = JSON.parse(event.data);
		} catch {
			return;
		}
		if (payload && typeof payload.slideId === "string") {
			restoreRegenButton(payload.slideId);
			if (payload.reason === "timeout") {
				showSaveToast("Regeneration timed out — try again", true);
			} else {
				showSaveToast("Regeneration failed", true);
			}
		}
	});

	events.addEventListener("deck-close", (event) => {
		isClosed = true;
		hideConfirmBar();
		stopHeartbeat();
		closeEvents();
		disableDeckInteractions();
		clearPendingGenerates();
		let reason = "closed";
		try {
			const payload = JSON.parse(event.data);
			if (payload && payload.reason) reason = payload.reason;
			if (payload && payload.reason === "submitted") {
				const submitButton = document.getElementById("btn-generate");
				if (submitButton) {
					submitButton.textContent = "Submitted";
					submitButton.disabled = true;
				}
			}
		} catch {}
		showCloseOverlay(reason);
	});
}

async function generateMore(button, slideId, input, countSelect) {
	if (isClosed || pendingGenerate.size > 0) return;

	const slideElement = document.querySelector(`.slide[data-id="${CSS.escape(slideId)}"]`);
	if (!slideElement) return;
	const optionsGrid = slideElement.querySelector(".options");
	if (!optionsGrid) return;

	const slide = slides.find((entry) => entry.id === slideId);
	if (!slide) return;

	const prompt = input ? input.value.trim() : "";
	if (input) input.value = "";

	const count = countSelect ? parseInt(countSelect.value, 10) || 1 : 1;

	// Create skeletons for each option being generated
	const skeletons = [];
	for (let i = 0; i < count; i++) {
		const skeleton = createElement("div", "option-skeleton");
		skeleton.innerHTML = '<div class="spinner"></div>';
		optionsGrid.appendChild(skeleton);
		skeletons.push(skeleton);
	}

	button.classList.add("loading");
	const plus = button.querySelector(".btn-gen-plus");
	if (plus) plus.textContent = "";
	button.lastChild.textContent = "Generating...";
	if (input) input.disabled = true;
	if (countSelect) countSelect.disabled = true;

	// Set timeout for generation (30s per option)
	const timeoutId = setTimeout(() => {
		const pending = pendingGenerate.get(slideId);
		if (pending && !pending.isRegen) {
			const received = pending.receivedCount || 0;
			restoreGenerateButton(slideId);
			if (received === 0) {
				showSaveToast("Generation timed out — try again", true);
			} else {
				showSaveToast(`Generated ${received} of ${count} options`, true);
			}
		}
	}, 30000 * count);

	pendingGenerate.set(slideId, { button, skeletons, input, countSelect, model: selectedModel || null, expectedCount: count, receivedCount: 0, timeoutId });

	try {
		const body = { token: [REDACTED], slideId, count };
		if (prompt) body.prompt = prompt;
		if (hasModelBar) {
			body.model = selectedModel;
			if (!selectedModel) body.thinking = selectedThinking;
		}
		await postJson("/generate-more", body);
	} catch {
		restoreGenerateButton(slideId);
	}
}

async function regenerateSlide(button, slideId) {
	if (isClosed || pendingGenerate.size > 0) return;

	const slideElement = document.querySelector(`.slide[data-id="${CSS.escape(slideId)}"]`);
	if (!slideElement) return;
	const optionsGrid = slideElement.querySelector(".options");
	if (!optionsGrid) return;

	const slide = slides.find((entry) => entry.id === slideId);
	if (!slide) return;

	const genRow = slideElement.querySelector(".gen-row");
	const input = genRow ? genRow.querySelector(".gen-prompt") : null;
	const prompt = input ? input.value.trim() : "";
	if (input) input.value = "";

	// Create skeleton overlay with centered spinner
	const optionCount = slide.options?.length || 2;
	const colClass = optionsGrid.classList.contains("cols-3") ? "cols-3" :
	                 optionsGrid.classList.contains("cols-1") ? "cols-1" : "cols-2";
	const overlay = createElement("div", `regen-overlay ${colClass}`);
	for (let i = 0; i < optionCount; i++) {
		overlay.appendChild(createElement("div", "regen-skeleton"));
	}
	const center = createElement("div", "regen-center");
	center.innerHTML = '<div class="spinner"></div><div class="regen-center-text">Regenerating options...</div>';
	overlay.appendChild(center);

	// Position overlay relative to options grid
	optionsGrid.style.position = "relative";
	optionsGrid.classList.add("regenerating");
	optionsGrid.appendChild(overlay);

	const originalText = button.textContent || "";
	button.classList.add("loading");
	button.disabled = true;
	button.textContent = "↻ Regenerating...";
	if (input) input.disabled = true;

	const genMoreBtn = slideElement.querySelector(".btn-gen-more");
	if (genMoreBtn) genMoreBtn.disabled = true;

	pendingGenerate.set(slideId, { button, originalText, input, isRegen: true, optionsGrid, genMoreBtn, overlay });

	try {
		const body = { token: [REDACTED], slideId };
		if (prompt) body.prompt = prompt;
		if (hasModelBar) {
			body.model = selectedModel;
			if (!selectedModel) body.thinking = selectedThinking;
		}
		await postJson("/regenerate-slide", body);
	} catch {
		restoreRegenButton(slideId);
	}
}

function restoreRegenButton(slideId) {
	const pending = pendingGenerate.get(slideId);
	if (!pending || !pending.isRegen) return;
	pendingGenerate.delete(slideId);

	const { button, originalText, input, optionsGrid, genMoreBtn, overlay } = pending;
	if (button) {
		button.classList.remove("loading");
		button.disabled = false;
		button.textContent = originalText || "↻ Regenerate all";
	}
	if (input) input.disabled = false;
	if (optionsGrid) {
		optionsGrid.classList.remove("regenerating");
		optionsGrid.style.position = "";
	}
	if (overlay && overlay.parentElement) {
		overlay.remove();
	}
	if (genMoreBtn) genMoreBtn.disabled = false;
}

// ─── INITIALIZATION ──────────────────────────────────────────

function initFooterControls() {
	if (btnBack) {
		btnBack.addEventListener("click", () => navigate(-1));
	}
	if (btnNext) {
		btnNext.addEventListener("click", () => navigate(1));
	}
}

function initConfirmBar() {
	const cancelBtn = document.getElementById("confirm-cancel");
	const keepBtn = document.getElementById("confirm-keep");
	if (cancelBtn) cancelBtn.addEventListener("click", () => cancelDeck("user"));
	if (keepBtn) keepBtn.addEventListener("click", () => hideConfirmBar());
}

function initSaveShortcut() {
	const isMac = navigator.platform.toUpperCase().indexOf("MAC") >= 0;
	document.querySelectorAll(".mod-key").forEach((el) => {
		el.textContent = isMac ? "⌘" : "Ctrl";
	});
	if (btnSave) {
		btnSave.addEventListener("click", () => saveDeck());
	}
	document.addEventListener("keydown", (e) => {
		const mod = isMac ? e.metaKey : e.ctrlKey;
		if (mod && e.key === "s") {
			e.preventDefault();
			saveDeck();
		}
	});
}

function hideLoadingOverlay() {
	const loader = document.getElementById("deck-loading");
	if (loader) {
		loader.classList.add("fade-out");
		setTimeout(() => loader.remove(), 300);
	}
}

function init() {
	initTheme();
	initLayoutToggle();
	setMetaLabel();
	renderSlides();
	restoreSelections();
	initFooterControls();
	initConfirmBar();
	initSaveShortcut();
	showSlide(0);
	startHeartbeat();
	connectEvents();
	fetchModels().then((data) => {
		if (data) initModelBar(data);
	});
	updateSaveStatus();

	document.addEventListener("keydown", handleKeydown);
	window.addEventListener("beforeunload", sendCancelBeacon);

	// Hide loading overlay after a brief moment for smooth transition
	requestAnimationFrame(() => {
		requestAnimationFrame(() => hideLoadingOverlay());
	});
}

init();
